INSERT INTO japanese_item (itemid, name, description) VALUES (176, 'スノーマンナイト', '騎士を模したサンドリア様式の雪像。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (177, 'スノーマンマイナー', '鉱山労働者を模したバストゥーク様式の雪像。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (178, 'スノーマンメイジ', '魔道士を模したウィンダス様式の雪像。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (179, 'ジェムエッグ', '祝祭に用いられるジュノ様式の飾卵。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (180, 'ボンボリ', '祝祭に用いられる東方様式を模した手燭。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (181, '王国旗', 'サンドリア王国の国旗。\n緋色の地は、誇り高きエルヴァーンの血統を表す。\nモチーフはドラギーユ家の紋章『神獣グリフィン』。');
INSERT INTO japanese_item (itemid, name, description) VALUES (182, '共和国旗', 'バストゥーク共和国の国旗。\n青色の地は、共和国首都を囲む滝と水運を表す。\nモチーフは共和国発展の原動力である水車と煙突。');
INSERT INTO japanese_item (itemid, name, description) VALUES (183, '連邦旗', 'ウィンダス連邦の国旗。\n緑色の地は、自然との調和を表す。\nモチーフは宗教シンボル『星の大樹』と5つの院。');
INSERT INTO japanese_item (itemid, name, description) VALUES (184, '大公国旗', 'ジュノ大公国の国旗。\n白色の地は、移民による歴史と中立主義を表す。\nモチーフは大陸に架けられた三基の橋と太陽。');
INSERT INTO japanese_item (itemid, name, description) VALUES (185, 'ルークバナー', 'コンフリクト『バリスタ』応援用に作られた旗標。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (186, 'シールドプラーク', '交差させた飾剣に凧形の盾を重ねた飾り板。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (187, 'バックラープラーク', '交差させた飾剣に円形の盾を重ねた飾り板。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (188, '若き召喚士の憂鬱', '人物画。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (189, 'グスタベルグの晩秋', '風景画。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (190, '線と面の数奇な邂逅', '抽象画。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (191, 'ポイント地図', '数々の穴場が記された釣り用の地図。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (192, '古塔', '水墨画。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (193, '冒険者感謝状', '三国指導者から冒険者に贈られた感謝状。\nサンドリア王、バストゥーク大統領\nウィンダス神子の署名がある。調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (194, '鍛冶師のプレート', '美しい黒鉄板に刻まれた認定賞。\nバストゥーク鍛冶ギルドから譲られた記念品。');
INSERT INTO japanese_item (itemid, name, description) VALUES (195, '海神の櫛', '巨大魚「タイタニックソー」の収縮凍結剥製。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (196, 'オルゴールエッグ', '祝祭に用いられるサンドリア様式のからくり卵。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (197, 'クロックエッグ', '祝祭に用いられるバストゥーク様式のからくり卵。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (198, '錦のタピストリー', '金糸が編みこまれた美麗な壁掛け。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (199, 'ラプトルエッグ', '祝祭に用いられるウィンダス様式のからくり卵。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (200, 'ツァヤンマスク', '南方の小国ツァヤに伝わる、森の精霊の仮面。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (201, 'トーテムポール', '西方の大陸ウルブカ伝来の祖霊を祀る飾り柱。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (202, '黄金の羊の毛皮', '陽光を受けると黄金色に輝く、伝説の羊の毛皮。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (203, 'ボムランタン', '祝祭に用いられるバストゥーク様式の飾提灯。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (204, 'パンプキンランタン', '祝祭に用いられるサンドリア様式の飾提灯。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (205, 'マンドラゴランタン', '祝祭に用いられるウィンダス様式の飾提灯。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (206, '太古の血潮', '抽象画。\n調度品の一種。');
