INSERT INTO japanese_item (itemid, name, description) VALUES (210, 'アースランプ', '土の属性を秘めたアトルガン様式の灯。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (211, 'サンダーランプ', '雷の属性を秘めたアトルガン様式の灯。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (212, 'ウォータランプ', '水の属性を秘めたアトルガン様式の灯。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (213, 'ライトランプ', '光の属性を秘めたアトルガン様式の灯。\n調度品の一種。');
