INSERT INTO japanese_item (itemid, name, description) VALUES (217, '黄銅の植木鉢', '黄銅でできた頑丈な植木鉢。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (218, '土師器の植木鉢', '土師器でできた安価な植木鉢。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (219, '陶器の植木鉢', '陶器でできた普通の植木鉢。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (220, '木の植木鉢', '木材でできた魔法の植木鉢。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (221, '謎の植木鉢', '奇妙な素材でできた植木鉢。\n耳を当てると、微音だが曲らしきものが聞こえる。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (222, '闘魚鉢', '闘魚鑑賞用の小型水槽。\n中でベタが泳いでいる。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (223, 'アクアリウム〔川〕', '淡水魚飼育用の水槽。\n中で3匹のカヤバルウが泳いでいる。\n調度品の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (224, 'アクアリウム〔湾〕', '海水魚飼育用の水槽。\n中で3匹のビビキーチョコボが泳いでいる。\n調度品の一種。');
