INSERT INTO japanese_item (itemid, name, description) VALUES (529, '夜光布', '暗闇でぼんやりと発光するアストラル物質の布。\n非常にもろく、加工は不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (530, '王城の設計図', 'ドラギーユ城改築時の設計図の写し。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (531, 'ラノリン', '羊毛から採れる脂をゴブリンが精製したもの。\nゴブリン石鹸の材料とされる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (532, '魔法用品店のチラシ', '羊皮紙でできたルジヌ魔法用品店のチラシ。\n魔法の特価セールが案内されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (533, 'デルフの腐葉土', 'デルフラントで採れる良質の腐葉土。\nクロウラーのフンが混じったものが最良とされる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (534, 'ゴゼビの野草', 'ギサールの野菜にそっくりな野草。\nチョコボに薬効があるが、不味いらしい。');
INSERT INTO japanese_item (itemid, name, description) VALUES (535, '紋章の刻まれたカギ', 'サンドリア王国の紋章が刻まれた黄銅製のカギ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (536, '冒険者優待券', '新規登録冒険者に便宜を図るための整理券。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (537, 'ガガンボの腹虫', 'ガガンボの腹中に潜む寄生虫。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (538, '呪われたサレコウベ', '何者かに拾われ、魂を呼び戻された頭蓋骨。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (539, '陸ガニのふんどし', '陸ガニの腹の部分の柔らかい甲殻。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (540, '血染めの衣', 'ゴーストが身にまとっていたボロボロの衣。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (541, 'ダルメルの唾液', '強烈な臭いを発するダルメルの唾液。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (542, '野兎の尻尾', '幸運を呼ぶ野兎の尻尾。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (543, 'ぼろぼろのカギ', '錆びつき、今にも折れ曲がりそうな鉄製のカギ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (544, '魔法試験の答案の束', 'ウィンダス魔法学校の試験の答案。\nひどく汚れている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (545, 'タルタル古銭', '貝殻でできたタルタルの古銭。\n');
