INSERT INTO japanese_item (itemid, name, description) VALUES (547, '墓守の革袋', '墓守が使っていた古びた革袋。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (548, '天晶堂への紹介状', '秘密貿易商会「天晶堂」への紹介状。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (549, 'デルクフのカギ', '複雑な形状のサーメット製のカギ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (550, '蒸気時計', '蒸気で時を刻むバストゥーク製の精巧な時計。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (551, '傷んだ星の木の実', 'カーディアンに装着されていた星の木の実。\n破損している。');
INSERT INTO japanese_item (itemid, name, description) VALUES (552, 'ヒウォンの髪', 'ヒウォンビォンの金色の毛髪。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (553, 'ダングルフの奇岩石', '血のように赤い貴石。\n伝説によると、ガルカの戦士の血が固まったもの。');
INSERT INTO japanese_item (itemid, name, description) VALUES (554, 'オークの黄金マスク', 'オークの王族が着用する黄金のかぶと。\n形状が特殊なため、人間は装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (555, '時計塔保存の嘆願書', 'ジュノ時計塔の取り壊しに反対する嘆願書。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (556, '占い玉', '占い用に磨きこまれた水晶玉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (557, 'アーリマンのレンズ', 'アーリマンから採取された巨大な水晶体。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (558, 'タルットカード愚者', 'タルタルが占いに用いるカード。\n「愚者」は正位置で自由、逆位置で逃避を表す。');
INSERT INTO japanese_item (itemid, name, description) VALUES (559, 'タルットカード亡者', 'タルタルが占いに用いるカード。\n「亡者」は正位置で悲哀、逆位置で開放を表す。');
INSERT INTO japanese_item (itemid, name, description) VALUES (560, 'ツェールンの煤', 'ツェールン鉱山の怪物に付着していた粉末。\n不安定な発火物質を含んでおり、危険。');
INSERT INTO japanese_item (itemid, name, description) VALUES (561, 'タルットカード王者', 'タルタルが占いに用いるカード。\n「王者」は正位置で統率、逆位置で不信を表す。');
INSERT INTO japanese_item (itemid, name, description) VALUES (562, 'タルットカード隠者', 'タルタルが占いに用いるカード。\n「隠者」は正位置で知識、逆位置で孤立を表す。');
INSERT INTO japanese_item (itemid, name, description) VALUES (563, 'グロコライト', '鈍い光沢を放つ、ごつごつした貴石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (564, '爪の入った麻袋', 'ゴブリンの爪コレクションが入った不潔な麻袋。\nゴブリンの腐茶の材料とされる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (565, '歯の入った麻袋', 'ゴブリンの虫歯コレクションが入った汚い麻袋。\nゴブリンの伝承では、虫歯は悪運を強める。');
INSERT INTO japanese_item (itemid, name, description) VALUES (566, 'ゴブリンカップ', 'ゴブリンが腐茶を淹れるのに用いる青銅製の容器。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (567, '井戸水', 'サンドリアの井戸で汲んだ水を満たした革袋。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (568, 'ゴブリンダイス', 'ゴブリンの遊戯「ミスラの尻尾」用のサイコロ。\n正確な多面体ではないため、目が偏るのがミソ。');
INSERT INTO japanese_item (itemid, name, description) VALUES (569, 'グスゲン鉱山の土', 'グスゲン鉱山の一角で採れた陶土。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (570, '碑文を写した粘土', '石碑に押し付け、碑文を写し取った粘土。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (571, 'セルビナの粘土', 'セルビナの近郊で採れる粘土。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (572, '謎の香草の種', '何かの香草の種。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (573, '謎の野菜の種', '何かの野菜の種。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (574, '謎の果物の種', '何かの果物の種。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (575, '謎の穀物の種', '何かの穀物の種。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (576, 'セイレーンの涙', '青い輝きを放つ涙滴型の貴石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (577, '黄銅のカギ', '黄銅でできた単純なつくりの鍵。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (578, 'ワシ印の銀ボタン', 'ワシが刻印された銀製のボタン。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (579, '形見の金縁めがね', '金のフレームで作られた眼鏡。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (580, '青銅の箱', '長い間、海の底に沈んでいた青銅製の箱。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (581, '星の木の実', '星の木から採れる白い実。\n魔法で加工され、カーディアンの頭に用いられる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (582, '隕石', '天から降ってきたと伝えられる黒い石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (583, '円石', '漬物の重しに丁度良い大きな楕円形の石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (584, '破れたラブレター', '男の宛名が記された恋文らしい封書。\n一部が破れてしまっている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (585, '泥だらけの請求書', '誰かの飲み食いについて書かれた紙。\n泥が付着して、すべては読めない。');
INSERT INTO japanese_item (itemid, name, description) VALUES (586, '怪しいカード', '何かの御祝いのために贈られたらしいカード。\nひどく汚れている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (587, 'しめった封筒', 'ロウで封印された封筒。\n濡れて歪んでしまっている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (588, 'みんなの美術　初級', 'ウィンダス文字で記された児童用の美術教本。\nペルメルやピソソといった有名画家の作品を収録。');
INSERT INTO japanese_item (itemid, name, description) VALUES (589, '若きコルモルの論文', 'コルモル博士が若い頃に著した論文。\n錬金術に関する研究が数百枚つづられている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (590, '航海帽子', '長年働いたベテランの航海士に贈られる黒い帽子。\n少年たちの憧れの的。');
INSERT INTO japanese_item (itemid, name, description) VALUES (591, '破れた帽子', '縫い目が解けて、破れてしまった黒い帽子。\n有名な航海帽子に似ている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (592, '食材の注文書', '「バタリア菜一把」と記された小さな紙片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (593, '魔法屋宛の小包', '「ルジヌ魔法用品店」宛ての小包。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (594, '競売所宛の小包', '「サンドリア北競売所」宛ての小包。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (595, '酒場宛の小包', '酒場「錆びた錨亭」宛ての小包。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (596, 'クゥダフの背甲', 'クゥダフが背に着用する複合装甲のよろい。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (597, '鉱山の砂利', 'バストゥーク周辺の鉱山から採取した砂。\nきらきらと光る鉱物が混じっている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (598, 'とんがり石', '複雑に割れて、あちこち尖っている石。\n陽光を受けると含有する鉱物がきらきらと輝く。');
INSERT INTO japanese_item (itemid, name, description) VALUES (599, 'ミスリルの砂粒', '鉱山の砂を精製して得られた霊銀の砂粒。\n純度が低く、鉱物的価値はあまりない。');
INSERT INTO japanese_item (itemid, name, description) VALUES (600, '手作りの軟膏', '貝殻に入れられた化膿止めの軟膏。\nつんと鼻をつく臭いがする。');
INSERT INTO japanese_item (itemid, name, description) VALUES (601, '軟膏の容器', '化膿止めの軟膏が入っていた貝殻の容器。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (602, '祝福された革袋', '高僧により女神の祝福を受けた水汲み用の革袋。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (603, 'シュヴァル川の水', 'シュヴァル川から汲んだ水で満たされた革袋。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (604, '古の予言書の一部', 'びっしりと古代文字が記されたパピルスの切れ端。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (605, 'つるはし', '鉱山労働者が坑道を掘削するために用いる道具。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (606, 'クゥダフ人形の頭', '黄銅でできたクゥダフの呪術用人形。\nその頭の部分。');
INSERT INTO japanese_item (itemid, name, description) VALUES (607, 'クゥダフ人形の胴', '黄銅でできたクゥダフの呪術用人形。\nその胴体の部分。');
INSERT INTO japanese_item (itemid, name, description) VALUES (608, 'クゥダフ人形の腕', '黄銅でできたクゥダフの呪術用人形。\nその腕の部分。');
INSERT INTO japanese_item (itemid, name, description) VALUES (609, 'クゥダフ人形の足', '黄銅でできたクゥダフの呪術用人形。\nその足の部分。');
