INSERT INTO japanese_item (itemid, name, description) VALUES (871, '朧な狼皮', 'アニマによって存在の薄れた狼の毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (872, '丈夫なダルメル革', 'アニマによって耐性の増したダルメルのなめし革。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (873, '軽量な雄羊革', 'アニマによって軽量化された雄羊のなめし革。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (874, 'アマルテアの毛皮', '燦然と輝きを放つ神山羊の毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (875, 'アマルテアなめし革', '耐久・耐火・耐水性に優れた神山羊のなめし革。\n');
