INSERT INTO japanese_item (itemid, name, description) VALUES (881, '陸ガニの甲殻', '頑丈な陸ガニの甲殻。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (882, '大羊の歯', '大羊の大きな臼歯。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (883, 'ベヒーモスの角', '巨大なベヒーモスの角。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (884, '黒虎の牙', '黒虎の長大な犬歯。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (885, '海亀の甲羅', '浜辺に打ち上げられた海亀の甲羅。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (886, '魔人のどくろ', '金属質を含む魔人の頭骨。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (887, '珊瑚のかけら', 'バストア珊瑚から剥離した欠片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (888, '貝殻', '大型二枚貝の殻。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (889, '甲虫の甲殻', '分厚い甲虫の頭部外骨格。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (890, '黒虎の屍の牙', '黒虎の長大な犬歯。\n死の直後に採取したもの。');
INSERT INTO japanese_item (itemid, name, description) VALUES (891, 'コウモリの牙', 'コウモリの小さな切歯。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (892, '古龍の頭骨', '太古の龍の石化した頭骨。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (893, '巨大な大腿骨', '丈夫な大型動物の大腿骨。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (894, '甲虫のアゴ', '鋭く尖った甲虫の顎。\n');
