INSERT INTO japanese_item (itemid, name, description) VALUES (896, '大サソリの甲殻', '軽くて丈夫な大サソリの甲殻。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (897, '大サソリの爪', 'しなやかで鋭い大サソリの爪。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (898, 'がら', '何かの鳥の骨。\nスープの味付けに使われる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (899, 'イフリートの角', '伝説の神獣イフリートの角。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (900, '魚の骨', '身が食され、頭と骨だけになった魚。\nゴブリンは頭を好むので、喜んで手に入れる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (901, '劇毒サソリの爪', '非常に強力な毒性のある大サソリの爪。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (902, '魔人の角', '金属質を豊富に含む魔人の角。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (903, '龍の爪', '巨大だが鋭いドラゴンの爪。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (904, '大魚の骨', '頭と骨だけになった何か大きな魚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (905, '飛竜の頭骨', '見た目よりも軽い飛竜の頭骨。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (906, '星喰い虫の甲殻', '甲虫「スターマイト」の頭部外骨格。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (907, '冷たい骨', '触ると、ぞっとする程ひんやりとする何かの骨片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (908, '金剛亀の甲羅', '非常に硬いアダマンタスの甲羅の欠片。\nアダマンチウムに匹敵する硬度を誇る。');
INSERT INTO japanese_item (itemid, name, description) VALUES (909, 'ギーヴルの頭骨', '飛竜の頭骨の中では比較的頑丈なギーヴルの頭骨。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (910, '暴走雄羊の角', '大羊のボス「ランベリングランバート」の角。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (911, '狂乱雄羊の角', '大羊のボス「ランページングラム」の角。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (912, '蜂の巣のかけら', '蜂の分泌物でできた巣の欠片。\n');
