INSERT INTO japanese_item (itemid, name, description) VALUES (914, '水銀', '銀色の液体金属。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (915, 'ガマの油', 'ヒキガエルが分泌する粘液。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (916, 'サボテンダーの針', 'サボテンダーの頭部から採られた鋭い針。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (917, '羊皮紙', '大羊の皮を加工して作られた紙。\n');
