INSERT INTO japanese_item (itemid, name, description) VALUES (919, 'ボヤーダ苔', 'グゥーブーの背に寄生する珍しい苔。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (920, 'モルボルのつる', 'モルボルから切り取られたつる。\n生命力が強く、時々ウネウネと動く。');
INSERT INTO japanese_item (itemid, name, description) VALUES (921, 'アーリマンの涙', 'アーリマンから採取された大粒の涙。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (922, 'コウモリの翼', '薄い膜のような黒い翼。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (923, '木霊の根', '精霊と化した樹木の根。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (924, '魔物の血', '魔物のものと思われる血液。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (925, '蜂の一刺し', '大蜂から切り取られた中空の針。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (926, 'トカゲの尻尾', 'トカゲから切り取られた尻尾。\n生命力が強く、時々ピクピクと動く。');
INSERT INTO japanese_item (itemid, name, description) VALUES (927, 'クァールの髭', 'クァールから切り取られたヒゲ。\n千里先の風を読むと伝えられる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (928, 'ボムの灰', 'ボムの燃えカス。\n');
