INSERT INTO japanese_item (itemid, name, description) VALUES (930, '獣人の血', '獣人のものと思われる血液。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (931, 'サーメットチップス', '錬金術で合成された超硬度の焼き物の素。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (932, 'カーボンファイバー', '錬金術で合成された炭の繊維束。\n弾性・耐熱性に優れる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (933, 'グラスファイバー', '錬金術で合成されたガラスの繊維束。\n耐熱性に優れる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (934, 'ユタンガの硫黄', 'ユタンガ山の火口付近から採取された硫黄。\n');
