INSERT INTO japanese_item (itemid, name, description) VALUES (936, '岩塩', '陸地で採れた塩の塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (937, 'にかわ', '皮や骨をぐつぐつ煮こんで作った接着剤。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (938, 'パパカ草', 'ダルメルの大好物と云われる草。\n小さな黄色い花を咲かせる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (939, 'ヘクトアイズの眼', 'ヘクトアイズから切り取られた、生きている眼球。\n見る力も失われず、放っておくと分裂し始める。');
INSERT INTO japanese_item (itemid, name, description) VALUES (940, '反魂樹の根', '伝説の反魂樹の根の一部。\n燃した煙をかけると、死者に生がもたらされる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (941, 'レッドローズ', '真赤なバラの花。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (942, '賢者の石', '錬金術師が探し求める究極の石。\n高度の錬金術には不可欠の材料とされる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (943, '毒素', '毒薬の材料となる粉末。\n');
