INSERT INTO japanese_item (itemid, name, description) VALUES (1088, '古代魔法のパピルス', '魔法について古の文字で記されたパピルス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1089, 'エクソレイの粘菌', '「エクソレイ」を形づくる粘菌の一部。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1090, 'ボムの炭', '「エクスプロージャー」によって炭化した物質。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1091, 'シャンデリアの灰', 'ボムの一種「シャンデリア」の燃えカス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1092, '王のダイス', '神の力が宿ると云われているゴブリンのサイコロ。\n名は、この力で王にまで上りつめた者の伝説から。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1093, '古のコイン', 'いつの時代のものか解らない、大昔のコイン。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1094, '釘抜き', 'クギを抜くために用いられる道具。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1095, '井戸のオモリ', '井戸のロープの先端につけられていた鉛のオモリ。\n強力のオークだけが、井戸を独占できる仕掛け。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1096, 'タブナジア通行手形', '先の戦争で滅びたタブナジア侯国の通行手形。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1097, 'ヤグードの聖水', '不死の者が近づかないよう、ヤグードが用いる水。\n彼らに伝わる秘法によって祝福されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1098, 'タブナジアの呼び鈴', '先の戦争で滅びたタブナジア侯家の呼び鈴。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1099, 'パラサイトの皮', 'ヤグードパラサイトのふにゃふにゃした皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1100, 'フー・サルモの羽根', 'ヤグードの英雄「野蛮なフー・サルモ」の羽根。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1101, 'クゥダフの斑卵', '斑模様のクゥダフの卵。\nこの卵から生まれた者は、高位を約束されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1102, '刺激がらし', '一般的に食用にはされない超激辛のスパイス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1103, 'ダボイ貯蔵庫のカギ', 'ダボイにある、オークの貯蔵庫のカギ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1104, '煌く奇石', '清らかな光を放つ不思議な石。\nもろいので、宝石的な価値はない。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1105, '種が入った袋', '星の木の種が入っている袋。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1106, 'ヤカマシ部屋のカギ', '騒々しい何者かが封じられている部屋のカギ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1107, '輝ける砂', 'キラキラと光を細かく乱反射する美しい砂。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1108, '硫黄', '火山地帯で採掘された硫黄。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1109, '人工レンズ', '錬金術師が作り出したレンズ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1110, '黒甲虫の体液', '黒色の甲虫から採取された体液。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1111, 'ゼラチン', '骨をぐつぐつ煮こんで作った食材。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1112, 'オークの鎧の小札', 'オークの戦士が身に着けていた鎧の一部。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1113, '古びたピアス', '薄汚れて傷の入ったピアス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1114, 'クゥダフ魔道士の血', '狡猾なクゥダフ魔道士が流した血液。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1115, 'スケルトンキー', '鍵を開けるためにシーフが用いる骨製のカギ。\n鍵穴を見て自在に鍵山を変形することが可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1116, '有翼獅子の毛皮', 'さらさらしたマンティコアの毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1117, '有翼獅子のなめし革', '強靭でなめらかなマンティコアのなめし革。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1118, 'アンティカの肩甲', 'アンティカの戦士が肩に着用する金属板のよろい。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1119, 'トンベリコート', 'トンベリが着用する小さな亜麻のコート。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1120, 'カサブランカ', '白色のカサブランカの花。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1121, 'アンティカのボロ', 'アンティカ労働者の木綿の着衣。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1122, '飛竜の皮', 'ごつごつした丈夫なワイバーンの皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1123, '有翼獅子の牙', 'マンティコアの巨大な犬歯。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1124, '飛竜の翼', 'ワイバーンから切り取られた巨大な翼。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1125, 'カーバンクルの紅玉', '意志を宿すと云われる、たいへん珍しい宝石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1126, '獣人印章', '粘土板に押し付けて使う獣人の判。\n獣人の関所で手形になるため、重宝されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1127, '獣神印章', '闇の血族が用いると伝えられる判。\n獣人拠点の手形となるため、貴重。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1128, 'バリスタ飛竜法典', 'バリスタルールブックの写本。\n黒の表紙に、ワイバーンの紋章が刻印されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1129, 'バリスタ鷲獅子法典', 'バリスタルールブックの写本。\n紫の表紙に、グリフィンの紋章が刻印されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1130, 'ムーンオーブ', '非常に硬そうに見える宝珠。\n \n（レベル制限:Lv61～は一時的にLv60になります）');
