INSERT INTO japanese_item (itemid, name, description) VALUES (1263, 'レショーンチの球根', '移動性植物「レーシィ」の幼体。\n仮死状態だが、養分を得ると動き始める。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1264, '大ボヤーダ苔', '長い間、グゥーブーの背で成長したボヤーダ苔。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1265, 'コリガンの四葉', 'たいへん珍しい四枚葉の「コリガン」の芽。\n悪運が強くなるとして、タルタルに珍重される。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1266, 'トンベリの鳴子', '何かが接触すると音が鳴るトンベリの警報装置。\nゴロゴロと不気味な音を発する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1267, '蜂の子', 'まんまると太った蜂の幼虫。\nもぞもぞと動いている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1268, 'ドールギズモ', 'ドールの体内にあった不可思議なパーツ。\nブゥンブゥンと奇怪な音を発している。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1269, 'マナバレル', 'マジックポットの体内にあった奇妙なパーツ。\nクプクプと奇妙な音を発している。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1270, 'アラクネの網', '「アラクネ」が作る巣の一部。\nアラクネ糸の原料となる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1271, 'ピジョンブラッド', '鳩の血のように赤い最高級のルビー。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1272, 'アリオクの牙', '「アリオク」の小さな切歯。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1273, 'ナムタルの骨', '「ナムタル」の小さな骨片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1274, '南洋真珠', '南洋で育ったシャル貝から採れる真珠。\n美しい光沢で知られる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1275, 'アメミットの皮', '分厚い「アメミット」の皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1276, 'タラスクの皮', '分厚い「タラスク」の皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1277, 'リンドウルムの皮', 'しなやかな「リンドウルム」の皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1278, '玉糸', 'ハベトロットの繭をつむいだ太い絹糸。\n太さが不均一で、織られた布は光を乱反射する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1279, 'タフタ織物', '複雑な工程を経て織られた光り輝く柔らかい織物。\n南方の国から伝来したもの。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1280, 'サーセネット織物', '複雑な工程を経て織られた木目細かな感触の織物。\n東方の国から伝来したもの。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1281, 'チェビオット織物', '珍しい羊の毛から織られた柔らかい織物。\n西方の島から伝来したもの。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1282, 'フラウロスの髭', '「フラウロス」から切り取られたヒゲ。\n未来の風を読むと伝えられる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1283, 'オセの髭', '「オセ」から切り取られたヒゲ。\n微かな風を読むと伝えられる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1284, '紅蓮金剛', 'アニマによって加熱されたアダマンチウム塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1285, '紫電金剛', 'アニマによって荷電されたアダマンチウム塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1286, '岩乗金剛', 'アニマによって硬化されたアダマンチウム塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1287, '凍寒金剛', 'アニマによって冷却されたアダマンチウム塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1288, 'ハクタクの木の眼', '木でできた、聖獣「ハクタク」の眼球。\n血と混ぜ合わせると、蘇ると云われている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1289, 'ハクタクの火の眼', '燃えさかる、聖獣「ハクタク」の眼球。\n血と混ぜ合わせると、蘇ると云われている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1290, 'ハクタクの土の眼', '土でできた、聖獣「ハクタク」の眼球。\n血と混ぜ合わせると、蘇ると云われている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1291, 'ハクタクの金の眼', '金でできた、聖獣「ハクタク」の眼球。\n血と混ぜ合わせると、蘇ると云われている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1292, 'ハクタクの水の眼', '水がしたたる、聖獣「ハクタク」の眼球。\n血と混ぜ合わせると、蘇ると云われている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1293, 'ナラシンハの毛皮', 'さらさらした「ナラシンハ」の毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1294, 'アラクネ糸', 'アラクネの網をつむいだ糸。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1295, 'ハベトロットの玉繭', '「ハベトロット」がクロウラーと共に作ったマユ。\n通常のクロウラーのマユより大きい。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1296, 'ヨーウィの皮', 'しなやかな「ヨーウィ」の皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1297, 'ナラシンハなめし革', '強靭でなめらかな「ナラシンハ」のなめし革。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1298, 'ハクタクの五行眼', '聖獣「ハクタク」の眼球の塊。\n分裂して、少しずつ増えつつある。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1299, '炎の宝珠', '炎の鉱石から削りだした玉。\n炎のエネルギーを帯びている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1300, '氷の宝珠', '氷の鉱石から削りだした玉。\n氷のエネルギーを帯びている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1301, '風の宝珠', '風の鉱石から削りだした玉。\n風のエネルギーを帯びている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1302, '土の宝珠', '土の鉱石から削りだした玉。\n土のエネルギーを帯びている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1303, '雷の宝珠', '雷の鉱石から削りだした玉。\n雷のエネルギーを帯びている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1304, '水の宝珠', '水の鉱石から削りだした玉。\n水のエネルギーを帯びている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1305, '光の宝珠', '光の鉱石から削りだした玉。\n光のエネルギーを帯びている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1306, '闇の宝珠', '闇の鉱石から削りだした玉。\n闇のエネルギーを帯びている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1307, '銀の葉', '葉脈がシルバーの輝きを放つ、珍奇な木の葉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1308, 'ミスリルの葉', '葉脈がミスリルの輝きを放つ、珍奇な木の葉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1309, '金の葉', '葉脈がゴールドの輝きを放つ、珍奇な木の葉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1310, '白金の葉', '葉脈がプラチナの輝きを放つ、珍奇な木の葉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1311, 'オックスブラッド', '非常に珍しい真紅の珊瑚の欠片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1312, 'エンゼルスキン', '珍しい薄桃色の珊瑚の欠片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1313, 'セイレーンの髪', 'セイレーンの言霊を秘めている金色の毛髪。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1314, '神木の免罪符：頭', '古の盟約に従い、神木はこの禁断の品を赦さん\nと記された護符。\n『呪われた頭成兜』の解呪に必要。');
