INSERT INTO japanese_item (itemid, name, description) VALUES (1344, '呪われた頭成兜', '漆の光沢が美しい東方風兜。\n呪われており、何人も装備できない。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1345, '祟られた頭成兜', '漆の光沢が美しい高品質の東方風兜。\n祟られており、何人も装備できない。');
