INSERT INTO japanese_item (itemid, name, description) VALUES (1441, '甘露の免罪符', '古の盟約に従い、甘露を食すことを赦さん\nと記された護符。\n『呪われた飲料』の解呪に必要。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1442, '供物の免罪符', '古の盟約に従い、供物を食すことを赦さん\nと記された護符。\n『呪われたスープ』の解呪に必要。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1443, '乾燥マグワート', 'マグワートを乾燥させたスパイス。\n消化活動を増進する効能がある。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1444, '神樹液', '御神木から抽出された樹液。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1445, 'フレイヤの涙', '高貴な輝きを放つ涙滴型の貴石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1446, 'ラッカー原木', '未加工のウルシの材木。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1447, 'ラッカー材', 'ウルシの材木。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1448, 'ラッカー樹液', 'ラッカー原木から抽出された樹液。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1449, 'トゥクク白貝貨', 'ウィンダスの旧通貨 1ムム。C.E.294年発行。\n星の神子トゥククが、タルタル諸部族を融和させ、\n連邦制に移行した記念に製作された初のムム貨幣。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1450, 'ルンゴナンゴ翠貝貨', 'ウィンダスの旧通貨百ムム。C.E.373年発行。\nエルヴァーン領に侵攻したルンゴナンゴ元帥が\nクォン大陸の南端に到達した記念に製作された。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1451, 'リミララ縞貝貨', 'ウィンダスの旧通貨 1万ムム。C.E.719年発行。\n星の神子リミララが魔法を発見してから\n500年を記念して製作された。縞は魔法の調和を表す。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1452, 'オルデール銅貨', 'サンドリアの旧通貨 1ノワ。C.E.491年発行。\n王立騎士団結成 100年を記念して鋳造された。\n名は初代団長フェンブルール・オルデール卿から。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1453, 'モニヨン銀貨', 'サンドリアの旧通貨百ノワ。C.E.563年発行。\n第一次コンシュタット会戦の勝利を記念して鋳造。\n名は一番槍をつけた騎士エルディ・モニヨンから。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1454, 'ランペール金貨', 'サンドリアの旧通貨 1万ノワ。C.E.830年発行。\n王都を襲った黒龍が退治された記念として鋳造。\n名は止めを刺したランペール・ドラギーユに由来。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1455, '1バイン紙幣', 'C.E.857年発行のバストゥークの旧通貨。\nセルビナ-マウラ機船定期便就航の記念紙幣。\n表にはつるはしと鉄砲、裏にはガルカの兵士を印刷。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1456, '100バイン紙幣', 'C.E.857年発行のバストゥークの旧通貨。\nセルビナ-マウラ機船定期便就航の記念紙幣。\n表には歯車、裏にはヒュームの技術者を印刷。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1457, '10,000バイン紙幣', 'C.E.857年発行のバストゥークの旧通貨。\nセルビナ-マウラ機船定期便就航の記念紙幣。\n表には大工房、裏には手を掲げる労働者たちを印刷。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1458, 'マンモスの牙', '最高の骨材と呼ばれる伝説の巨大獣の門歯。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1459, 'グリフィンなめし革', '丈夫だが驚くほど軽いグリフィンのなめし革。\n');
