INSERT INTO japanese_item (itemid, name, description) VALUES (1469, 'ウーツ鉱', '天然のウーツ合金を含有する鉱石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1470, '輝く透石', '透明の宝石を含んでいることがある石。\n');
