INSERT INTO japanese_item (itemid, name, description) VALUES (1472, 'ガーディニアの実', '染料や魔除けとして用いられるスパイス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1473, '上質なサソリの甲殻', '状態のよい大サソリの甲殻。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1474, 'インフィニティコア', '「動く巨像」の体内から取り出した心臓。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1475, 'カレーパウダー', '二十一種の南方のスパイスを混ぜ合わせた調味料。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1476, 'シフートの弦', 'シフートと云う楽器の一部。共鳴箱に張る獣毛。\nアンティカ頸部の摩擦音に似た擬音を出せるため\n他種族が彼らと直接対話する際に用いられる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1477, 'シフートの共鳴箱', 'シフートと云う楽器の本体。中空の木箱。\nアンティカ頸部の摩擦音に似た擬音を出せるため\n他種族が彼らと直接対話する際に用いられる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1478, 'シフートの弓', 'シフートと云う楽器の演奏に用いられる道具。\nアンティカ頸部の摩擦音に似た擬音を出せるため\n他種族が彼らと直接対話する際に用いられる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1479, 'シフートの調律輪', 'シフートと云う楽器の一部。調音に用いるパーツ。\nアンティカ頸部の摩擦音に似た擬音を出せるため\n他種族が彼らと直接対話する際に用いられる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1480, '人魚の木乃伊の頭', 'ヒュームの伝説の人魚を思わせる、干からびた頭。\n実はサハギンが海賊と物々交換する商品として、\nオポオポの死体から製作した精巧な細工物。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1481, '人魚の木乃伊の体', 'ヒュームの伝説の人魚を思わせる、干からびた体。\n実はサハギンが海賊と物々交換する商品として、\nオポオポの死体から製作した精巧な細工物。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1482, '人魚の木乃伊の手', 'ヒュームの伝説の人魚を思わせる、干からびた手。\n実はサハギンが海賊と物々交換する商品として、\nオポオポの死体から製作した精巧な細工物。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1483, '人魚の木乃伊の尾', 'ヒュームの伝説の人魚を思わせる、干からびた尾。\n実はサハギンが海賊と物々交換する商品として、\nプギルの死体から製作した精巧な細工物。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1484, '死のマントル', '蜘蛛の網のようなトンベリランタンの発光筒。\nトンベリのアサシン（暗殺者）専用のタイプで、\nその光で敵に催眠術をかけることができると云う。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1485, '死のグローブ', '甲虫の甲殻から作られたトンベリランタンの火屋。\nトンベリのアサシン（暗殺者）専用のタイプで、\nその光で敵に催眠術をかけることができると云う。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1486, '死のファウント', '悪臭を発するトンベリランタンの油壺。\nトンベリのアサシン（暗殺者）専用のタイプで、\nその光で敵に催眠術をかけることができると云う。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1487, '死のベンチレーター', '人骨から作られたトンベリランタンの排気傘。\nトンベリのアサシン（暗殺者）専用のタイプで、\nその光で敵に催眠術をかけることができると云う。');
