INSERT INTO japanese_item (itemid, name, description) VALUES (1514, 'チョコボ優待券', 'チョコボ厩舎が騎行普及のために発行している\n無料乗鳥券。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1515, '牙の矢尻', 'ファングアローの先端にとりつけるパーツ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1516, 'グリフィンの毛皮', 'きらきらしたグリフィンの毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1517, '氷漬けの巨大な頭', '何か巨大な生物の頭が入った凍土の塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1518, '巨大なサレコウベ', '半ば化石化した巨大な頭蓋骨。\nヒュームのそれに似ている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1519, '臙脂の肝', '頑健なオークから切り取られた肝の臓。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1520, 'ゴブリングリース', 'ゴブリンの錬金術師が調合した秘伝の潤滑剤。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1521, 'スライムジュース', '珍種のスライムから抽出した希少な体液。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1522, 'マージョラム', '消臭効果があるスパイス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1523, 'アップルミント', '鎮静・消化促進効果があるハーブ。\nリンゴに似た香りがする。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1524, 'マグワート', '消化促進効果があるスパイス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1525, 'アダマンタスの卵', '巨亀アダマンタスの小さな卵。\n殻に金属が混じっていて、鉱石のように見える。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1526, 'ウィルムの逆鱗', '真龍ウィルムの逆さまに生えたウロコ。\n顎の下に1枚だけある。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1527, 'ベヒーモスの舌', '恐獣ベヒーモスの巨大な舌。\n無数の突起が表面にびっしりと生えている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1528, '赤の色報石', 'オークが軍令伝達に使う色のついた石。\n赤い色より「ロンフォール」\n打ち込まれた釘の数より「襲撃」と読みとれる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1529, '黒の字刻板', 'ダーク板でできたクゥダフの作戦指令書。\n「グスタベルグ」らしき地図が刻まれており\nその上から進撃ルートが描き込まれている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1530, '七結節のキープス', 'ヤグードの伝令が携える、結び縄文字の教書。\n結び方が行動、間隔が時、数が場所を表すとされ、\n「7」が「サルタバルタ」を\n「仲仕結び」が「攻略」を指している。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1531, 'ガルカ牙入り麻袋', 'ゴブリンの盗賊団が通信に用いる麻袋。\n中には、たくさんの獣歯に混じって\n「ザルクヘイム」を意味すると云われる\n穿孔されたガルカの牙が入っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1532, '翠の色報石', 'オークが軍令伝達に使う色のついた石。\n緑色より「ノルバレン」\n打ち込まれた釘の数より「襲撃」と読みとれる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1533, '銀の字刻板', '銀板でできたクゥダフの作戦指令書。\n「デルフラント」らしき地図が刻まれており\nその上から進撃ルートが描き込まれている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1534, 'ミスラ牙入り麻袋', 'ゴブリンの盗賊団が通信に用いる麻袋。\n中には、たくさんの獣歯に混じって\n「コルシュシュ」を意味すると云われる\n穿孔されたミスラの牙が入っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1535, '十三結節のキープス', 'ヤグードの伝令が携える、結び縄文字の教書。\n結び方が行動、間隔が時、数が場所を表すとされ、\n「13」が「アラゴーニュ」を\n「仲仕結び」が「攻略」を指している。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1536, '黒虎革の密書', 'かつて獣人軍で用いられていた、なめし革の密書。\n象形文字で書かれているが、\n一部の解読法は冒険者にも知られており\n「フォルガンディ」と読める。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1537, 'ベヒーモス革の密書', 'かつて獣人軍で用いられていた、なめし革の密書。\n象形文字で書かれているが、\n一部の解読法は冒険者にも知られており\n「バルドニア」と読める。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1538, '雄羊革の密書', 'かつて獣人軍で用いられていた、なめし革の密書。\n象形文字で書かれているが、\n一部の解読法は冒険者にも知られており\n「クフィム」と読める。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1539, '地獄猟犬牙入り麻袋', 'ゴブリンの盗賊団が通信に用いる麻袋。\n中には、たくさんの獣歯に混じって\n「リ・テロア」を意味すると云われる\n穿孔されたヘルハウンドの牙が入っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1540, 'ダルメル革の密書', 'かつて獣人軍で用いられていた、なめし革の密書。\n象形文字で書かれているが、\n一部の解読法は冒険者にも知られており\n「クゾッツ」と読める。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1541, '浜兎牙入り麻袋', 'ゴブリンの盗賊団が通信に用いる麻袋。\n中には、たくさんの獣歯に混じって\n「ヴォルボー」を意味すると云われる\n穿孔されたビーチバニーの牙が入っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1542, '大羊革の密書', 'かつて獣人軍で用いられていた、なめし革の密書。\n象形文字で書かれているが、\n一部の解読法は冒険者にも知られており\n「低地エルシモ」と読める。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1543, 'クァール革の密書', 'かつて獣人軍で用いられていた、なめし革の密書。\n象形文字で書かれているが、\n一部の解読法は冒険者にも知られており\n「高地エルシモ」と読める。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1544, '火の音叉・改', 'ウィンダスの鼻の院が改良を加えた特殊な音叉。\n');
