INSERT INTO japanese_item (itemid, name, description) VALUES (1546, '風の音叉・改', 'ウィンダスの鼻の院が改良を加えた特殊な音叉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1547, '土の音叉・改', 'ウィンダスの鼻の院が改良を加えた特殊な音叉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1548, '雷の音叉・改', 'ウィンダスの鼻の院が改良を加えた特殊な音叉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1549, '水の音叉・改', 'ウィンダスの鼻の院が改良を加えた特殊な音叉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1550, '五戦士魔法陣', '光るインクで魔法陣が描かれた羊皮紙。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1551, 'クラウディオーブ', '非常に硬そうに見える宝珠。\n \n（レベル制限:Lv21～は一時的にLv20になります）');
INSERT INTO japanese_item (itemid, name, description) VALUES (1552, 'スカイオーブ', '非常に硬そうに見える宝珠。\n \n（レベル制限:Lv31～は一時的にLv30になります）');
INSERT INTO japanese_item (itemid, name, description) VALUES (1553, 'テミスオーブ', '曇って中の様子がよく見えない宝珠。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1554, 'ターメリック', 'ウコンの根茎を乾燥させたスパイス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1555, 'コリアンダー', 'コリアンダーの実を乾燥させたスパイス。\n');
