INSERT INTO japanese_item (itemid, name, description) VALUES (1583, '剛弓の欠片', '禁断の弓の一部。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1584, '魔笛の欠片', '禁断の楽器の一部。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1585, '名銃の欠片', '禁断の銃の一部。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1586, '甲冑魚の甲殻', '巨大な甲冑魚の甲殻。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1587, '上質な魚の鱗', '状態のよい大型魚のウロコ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1588, '凝灰岩', '火砕岩を加工した石材。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1589, 'プシュケー', 'デュナミスに心囚われた魂の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1590, 'ホーリーバジル', '強い芳香を放つ葉のスパイス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1591, '上質なクァール毛皮', '状態のよいクァールの毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1592, 'サボテンダーの根', '組織が足として発達している特殊な根。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1593, '災厄のロウソク', 'ヒュームの叙事詩に登場する悪魔の蝋燭。\n主人公の皇帝は、この蝋燭を灯したが故に、\n数々の災厄に見舞われてしまう。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1594, '血糊のロウソク', 'ヒュームの叙事詩に登場する死神の蝋燭。\n主人公の女帝は、この蝋燭を灯したが故に、\n己の命脈を縮めることになってしまう。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1595, '囁きの書', 'エルヴァーンの誓いの儀式に用いられる禁書。\n現世のあらゆる快楽が記されているとされている。\nただし、誘惑に勝てず覗き見た者は、\n死後、魂の獄に囚われると云う。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1596, '呻きの書', 'エルヴァーンの誓いの儀式に用いられる占星書。\n読むと、自分の未来が分かるとされている。\nただし、誘惑に勝てず覗き見た者は、\n死後、魂の獄に囚われると云う。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1597, '嘲笑うドクロ', 'タルタルの子守唄に登場する頭蓋骨。\nいつまでも遊んでる悪い子には、\nゲラゲラドクロがやってくる。\nつい貰い笑いしたら止まらなくなるという怖い唄。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1598, '啜り泣くドクロ', 'タルタルの子守唄に登場する頭蓋骨。\nいつまでも起きてる悪い子には、\nシクシクドクロがやってくる。\nつい貰い泣きしたら止まらなくなるという怖い唄。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1599, 'ヨアトル蚤', 'ミスラの噂話で怖れられているノミ。\nこのノミに刺されると、\n全身が痒くなり、数日間眠れなくなるらしい。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1600, 'しっぽ斬り', 'ガルカの怪談に登場する呪われた包丁。\nこの包丁で尻尾を切断されると、\n二度と生えてこないと云う。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1601, 'マネキンヘッド', '木製マネキンの頭部パーツ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1602, 'マネキンボディ', '木製マネキンの胴部パーツ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1603, 'マネキンハンズ', '木製マネキンの手部パーツ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1604, 'マネキンレッグズ', '木製マネキンの脚部パーツ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1605, 'マネキンフィート', '木製マネキンの足部パーツ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1606, '激しき記憶の残滓', '記憶をわずかにとどめた「虚ろなるもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1607, '哀しき記憶の残滓', '記憶をわずかにとどめた「虚ろなるもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1608, '空しき記憶の残滓', '記憶をわずかにとどめた「虚ろなるもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1609, '楽しき記憶の残滓', '記憶をわずかにとどめた「虚ろなるもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1610, '輝かしき記憶の残滓', '記憶をわずかにとどめた「虚ろなるもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1611, '忌わしき記憶の残滓', '記憶をわずかにとどめた「虚ろなるもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1612, '眩しき記憶の残滓', '記憶をわずかにとどめた「虚ろなるもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1613, '悪しき記憶の残滓', '記憶をわずかにとどめた「虚ろなるもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1614, 'コースの腕輪', '不死なる者「コース」が着用する琥珀の腕輪。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1615, '野牛の角', '立派にくねりまがったバッファローの角。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1616, 'アントリオンの大顎', '砂蟲アントリオン族の巨大なアゴ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1617, 'フライトラップの葉', '飛行植物フライトラップ族の翼となる葉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1618, 'ウラグナイトの殻', 'ウラグナイト族の背負っている大きな貝殻。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1619, 'ヒポグリフの羽根', 'ヒポグリフの頭に生えている羽根。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1620, 'タウルスの角', '大きく湾曲したタウルスの角。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1621, 'タウルスの翼', 'タウルスから切り取られた奇怪な翼。\n傷口はきれいに塞がっている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1622, 'ブガードの牙', 'ブガードの発達した歯。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1623, 'エフトの皮', '細鱗が煌めくエフトの皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1624, 'バグベアマスク', 'バグベアが着用する革の防毒マスク。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1625, 'モブリンヘルム', 'モブリンが着用する黄銅でできた冑。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1626, '霊獣の血', '霊獣のものと思われる血液。\n淡い光を放っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1627, '徹甲の矢尻', 'ボドキンアローの先端にとりつけるパーツ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1628, '野牛の毛皮', 'がさがさしたバッファローの毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1629, '野牛のなめし革', '厚くて丈夫なバッファローのなめし革。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1630, 'クラスターの灰', 'クラスターの燃えカス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1631, 'モブリンアーマー', 'モブリンが着用する革と布でできた鎧。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1632, 'モブリンメイル', 'モブリンが着用する黄銅でできた鎧。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1633, 'ミニクロット', 'スライム族の亜種「クロット」の小型の分身。\n毒素を抜くと、食用に適する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1634, 'ロードナイト', '紅色の宝石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1635, 'パクタンインゴット', '製錬した白銅の塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1636, 'モブリン織物', 'モブリン糸を編んで作った布。\n丈夫で軽量。耐熱性にも優れる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1637, 'ブガードのなめし革', '優れた耐久性を誇るブガードのなめし革。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1638, 'モブリンマスク', 'モブリンが着用する革の防塵マスク。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1639, 'コースの法衣', '不死なる者「コース」が着用するビロードの衣。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1640, 'ブガードの皮', '瘤の多いゴツゴツしたブガードの皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1641, '炎のアニマ', '炎の属性を帯び、半実体化した擬似魂。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1642, '氷のアニマ', '氷の属性を帯び、半実体化した擬似魂。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1643, '風のアニマ', '風の属性を帯び、半実体化した擬似魂。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1644, '土のアニマ', '土の属性を帯び、半実体化した擬似魂。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1645, '雷のアニマ', '雷の属性を帯び、半実体化した擬似魂。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1646, '水のアニマ', '水の属性を帯び、半実体化した擬似魂。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1647, '光のアニマ', '光の属性を帯び、半実体化した擬似魂。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1648, '闇のアニマ', '闇の属性を帯び、半実体化した擬似魂。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1649, '紅石', '紅色の宝石を含んでいることがある石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1650, '魔銅鉱', '金属の魔銅を含有する鉱石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1651, 'モブリン糸', 'モブリンが開発した人造繊維から作られた糸。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1652, 'ライスビネガー', '米から作られた東方伝来の酢。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1653, 'デーモンの指ペン', 'デーモンの指で作られたペン。\n血がインクに、爪がペン先になる。\n紙に置くと、ひとりでに動いて日誌を書きつける。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1654, '火成岩', 'マグマが固まってできた岩石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1655, 'シープポーチ', '羊のなめし革で作られた小さな袋。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1656, 'ブラスタンク', 'ブラス板で作られた液体用の密閉容器。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1657, '結束ロープ', '木工ギルドで原木を束ねるのに使用されるロープ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1658, '海獅子の紋章のカギ', '海獅子の紋章が刻印された黄銅の鍵。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1659, '珊瑚の紋章のカギ', '珊瑚の紋章が刻印された黄銅の鍵。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1660, '青銅のカギ', '青銅でできた単純なつくりの鍵。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1661, 'ミザレオのにんにく', '独特の臭いと滋養強壮を備えたスパイス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1662, '国教会認定聖布', '聖人が生前に使用していた布。\nサンドリア国教会により認定済みの品。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1663, 'アルニカの根', '多年草アルニカの根。\n傷の治癒や解熱の効能がある。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1664, '東方の玉璧', '東方で珍重される平たく円い翡翠。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1665, '純銅のカギ', '純銅でできた単純なつくりの鍵。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1666, 'カメレオンダイヤ', '周囲の温度によって色を変えるダイアモンド。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1667, 'クラスターの魂', 'クラスターの燃えさかる魂。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1668, '綺麗な折れ口の釣竿', '折れてしまった『渓流竿』。\n折れ口が不自然なほど鮮やかだ。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1669, '古代ボムの灰', '「エンシェントボム」の燃えカス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1670, '岩乗オリハルコン', 'アニマによって硬化されたオリハルコン塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1671, '破邪のアッシュ', 'アニマによって呪文を解くアッシュ材。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1672, '破魔の白樫', 'アニマによって魔法を跳ね返すホワイトオーク材。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1673, '飛天の白樫', 'アニマによって転移するホワイトオーク材。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1674, '硬化黄金', 'アニマによって硬度の増した金の塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1675, '解毒白銀', 'アニマによって解毒効果を得た銀の塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1676, '凍寒オリハルコン', 'アニマによって冷却されたオリハルコン塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1677, '誘水のオリハルコン', 'アニマによって水を呼ぶオリハルコンの塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1678, '盗賊の白銀', 'アニマによって輝きの増した銀の塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1679, '破邪の黄金', 'アニマによって呪文を解く金の塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1680, '上質なブガードの皮', '状態のよいブガードの皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1681, '軽量鋼', 'アニマによって軽量化された鋼の塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1682, '王国認定ゴールド', 'サンドリア王国の備蓄金として鋳造された金の塊。\n中央に小さくグリフィンが刻印されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1683, 'アットワジンセン', 'アットワ地溝にのみ自生する薬用人参。\n滋養強壮の効能があり、高値で取引される。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1684, '黄金のカギ', '黄金製の精巧なつくりの鍵。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1685, '降魔の油', 'クゥダフの夜警が用いる灯油。\n燃焼する時に発する独特の芳香が、怪物を退ける。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1686, '汚れた封筒', 'ロウで封印された封筒。\n汚れてしまっている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1687, '恐ろしき記憶の一塊', 'かなり記憶をとどめた「虚ろなるもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1688, '悩ましき記憶の一塊', 'かなり記憶をとどめた「虚ろなるもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1689, '疾しき記憶の一塊', 'かなり記憶をとどめた「虚ろなるもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1690, 'ヒポグリフの尾羽根', 'ヒポグリフの尾に生えている羽根。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1691, '巨大な鱗', '巨大な真龍のものと思われる1枚の鱗。\n淡い光を放っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1692, 'カーマインチップ', '半透明な紅色の小さな六角形の板。\n中を覗くと、瞬く無数のラインが見える。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1693, 'シアンチップ', '半透明な青緑色の小さな六角形の板。\n中を覗くと、瞬く無数のラインが見える。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1694, 'グレーチップ', '半透明な灰白色の小さな六角形の板。\n中を覗くと、瞬く無数のラインが見える。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1695, 'ハバネロ', '「刺激がらし」より辛いと評判のスパイス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1696, '魔炉鋼', '魔炎の燃え盛る炉で精製された特殊な鋼。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1697, 'スプルース材', 'トウヒの材木。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1698, '油目ヤスリ', '非常に細かい目のヤスリ。\nデーモンが爪を研ぐのに使っているらしい。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1699, '緋麻布', '血糸と亜麻糸を編んで作った布。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1700, '血糸', 'ダイアマイトの一種が吐く、血のように赤い糸。\n風に流して獲物を捕えるため、軽いがとても丈夫。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1701, '薄い亜麻布', 'アニマによって薄くなった亜麻布。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1702, '滑らかなビロード', 'アニマによって滑らかになったビロード。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1703, '昆吾石', '金属の昆吾鉄を含有する鉱石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1704, '昆吾鉄', '東方の製法による昆吾鉄の塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1705, '昆吾板', '昆吾鉄の板。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1706, 'ニュモモちゃん', 'ジュノで爆発的ブームを呼んでいる、女児用玩具。\nおしゃまで気まぐれな架空のタルタル少女の\n活躍を描いた同名絵草子のキャラクターグッズ。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1707, '東方の紙', '東方の優れた製紙技術で作られた高級紙。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1708, 'ゴブリンの贋ギル', 'ゴブリンが偽造した精巧なギル貨幣。\nただし、魔法の透かし彫が入っていないため、\n商人なら本物と見分けるのは容易い。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1709, 'ナフィルのバッグ', '高級皮革ブランド、ナフィル製のハンドバッグ。\nブランド名は、創業者の伝説的革工ナフィルから。\nジュノ社交界必携のアイテム。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1710, 'フェルナン様の一日', 'ジュノで大人気の舞台俳優の密着取材記。\n彼が1日に発した言葉から何気ない仕草まで、\n写実的なイラストと共に綴るファン垂涎の1冊。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1711, 'モリブデインゴット', '製錬したモリブデン鋼の塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1712, 'カシミヤ毛', '鮮やかな光沢の大羊の長毛。\n近東に生息する大羊の一種からのみ採れる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1713, 'カシミヤ糸', 'カシミヤ毛をつむいだ糸。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1714, 'カシミヤ織物', 'カシミヤ糸を編んで作った最高級の毛織物。\nとても柔軟で、保温性に優れる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1715, '蘇生珊瑚', 'アニマによって蘇生し始めた珊瑚のかけら。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1716, '滑らかな甲虫の顎', 'アニマによって滑らかになった甲虫のアゴ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1717, '現のアニマ', 'すべての属性を帯び、実体化した擬似魂。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1718, 'メガロブガードの牙', '「メガロブガード」の湾曲した巨大な牙。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1719, 'ハラジナイトの殻', '「ハラジナイト」の背負っている巨大な貝殻。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1720, '水色の記憶の結晶', '結晶化した「虚ろなるもの」の断片。\n水色にゆらめく光を放っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1721, '緑色の記憶の結晶', '結晶化した「虚ろなるもの」の断片。\n緑色にゆらめく光を放っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1722, '青色の記憶の結晶', '結晶化した「虚ろなるもの」の断片。\n青色にゆらめく光を放っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1723, '白色の記憶の結晶', '結晶化した「虚ろなるもの」の断片。\n白色にゆらめく光を放っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1724, 'ソウルフレアの衣', 'ソウルフレアの絹の長衣。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1725, 'スノーリリー', '雪の中に咲く、珍しい高山性の百合。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1726, 'イーグレットの釣竿', '昔、漁師ギルドで扱っていた超高級ブランド釣竿。\n折れてしまっている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1727, 'ガラダヤチーク材', '南方のガラダヤ島産の高級材木。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1728, 'オードリナイト', '莫大なエネルギーを生むと伝えられる鉱石。\n太陽にかざすと、淡い光を放つ。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1729, 'モブリンの温石', 'こすると高熱を発する不思議な石。\n火気厳禁の坑内で、モブリンが調理に用いている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1730, 'ポーラファー植木鉢', '成長を遅らせる植木鉢に移し変えられた北極樅。\nただし、長い間植えられていると、枯れてしまう。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1731, 'ナイツジングルベル', 'かつて王立騎士に流行した、チョコボにつける鈴。\n美しい音色だが、敵には発見され易かった。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1732, '樹氷に覆われた苗木', '美しい樹氷に覆われた樹。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1733, '雪氷の珠', '丸く削られた氷の珠。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1734, 'ブルーバンドー', '輝く青いビロードの帯。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1735, 'クェ・パイ', '狩人クェ・ロンチャブが焼いたミートパイ。\n美味しいけれど、冷めると臭味が出てしまう。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1736, 'メヒルルジェラート', '黒魔道士メヒルルの開発した氷菓子。\n美味しいけれど、融けやすいのが難点。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1737, '翡翠の珠', '丸く削られた翡翠の珠。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1738, '赤銅の鋳塊', '東方より伝来した赤銅のインゴット。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1739, 'バルーンクロス', '気球に使われていた丈夫な綿布。\nかつて、バストゥークで織られたもののようだ。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1740, 'アイオライト', '青色の宝石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1741, '上質なエフトの皮', '状態のよいエフトの皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1742, '子供へのプレゼント', '子供の喜びそうな品が入った箱。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1743, '子供へのプレゼント', '子供の喜びそうな品が入った箱。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1744, '子供へのプレゼント', '子供の喜びそうな品が入った箱。\n');
