INSERT INTO japanese_item (itemid, name, description) VALUES (1746, 'ＳＢへの感謝の手紙', '子供から預かったスマイルブリンガー宛ての手紙。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1747, 'ＳＢへの御礼の手紙', '子供から預かったスマイルブリンガー宛ての手紙。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1748, 'ＳＢへの喜びの手紙', '子供から預かったスマイルブリンガー宛ての手紙。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1749, 'エビス割符', '天晶堂が発行した証書。\n釣竿と陸魚を腕に抱いた狩人が描かれている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1750, 'ビシャモン割符', '天晶堂が発行した証書。\n東方の甲冑をつけた猛々しい戦士が描かれている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1751, 'ホテイ割符', '天晶堂が発行した証書。\n東方の装束を着た福々しいモンクが描かれている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1752, 'ベンテン割符', '天晶堂が発行した証書。\n見目麗しい吟遊詩人の娘が描かれている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1753, 'ダイコク割符', '天晶堂が発行した証書。\nハンマーを持った白魔道士の男が描かれている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1754, 'ジュロウジン割符', '天晶堂が発行した証書。\n大羊を従えた獣使いの老人が描かれている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1755, 'フクロクジュ割符', '天晶堂が発行した証書。\nスタッフを持った長頭の召喚士が描かれている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1756, '考えるものの残滓', '「考えるもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1757, '欲するものの残滓', '「欲するもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1758, '飽きるものの残滓', '「飽きるもの」の断片。\n');
