INSERT INTO japanese_item (itemid, name, description) VALUES (1760, '忌忌しき記憶の一塊', 'かなり記憶をとどめた「虚ろなるもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1761, '禍禍しき記憶の一塊', 'かなり記憶をとどめた「虚ろなるもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1762, '鉄刀木材', 'タガヤサンの材木。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1763, '青漆', '東方伝来の青緑色の塗料。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1764, '毛繻子', '綿糸と毛糸より織られた、滑らかで光沢のある布。\n東方から伝来したもの。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1765, '波布の皮', '東方の動物ハブの皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1766, 'タイガーアイ', '茶色の宝石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1767, '霊牛のなめし革', '伝説の牛の、古びたなめし革。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1768, '羚羊のなめし革', '南方の動物レイヨウのなめし革。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1769, 'ガラティーア', '白地に染められた、非常に丈夫な高級綿布。\n西方から伝来したもの。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1770, '巨大な牙', '何らかの巨大生物の発達した門歯。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1771, '龍骨', '古の龍のものと思われる、巨大な大腿骨。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1772, 'スーパーサーメット', '超々硬度の焼き物の素。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1773, 'ダークの小札', '小さな黒鉄板。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1774, '赤玉土', 'ぽろぽろした赤褐色の粒でできた用土。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1775, '陰火薬', 'アニマによって調合された、強力な発火薬。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1776, 'スパゲティ', '細長い棒状にしたデュラムセモリナ粉の固まり。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1777, '厚手の麻袋', 'ジャカカから預かった大きな麻袋。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1778, 'パラダモの石', 'パラダモの丘の頂で拾った浮石をつめた麻袋。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1779, '厚手の木綿袋', 'ゼバダから預かった大きな木綿袋。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1780, 'シャムナエの氷', 'シャムナエの泉から採った氷をつめた木綿袋。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1781, 'シルバンストーン', '緑色の美しい玉。\n森の匂いがすると云われる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1782, 'フロリドストーン', '赤色の美しい玉。\n血の臭いがすると云われる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1783, 'ルミニアン組織', '無色無味無臭のルミニアンの肉。\n光を放つ微粒子が、表面から放出されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1784, 'フワボ器官', 'ルミニアン「フワボ」の独立構造体。\n光を放つ微粒子が、表面から放出されている。');
