INSERT INTO japanese_item (itemid, name, description) VALUES (1786, 'アーン器官', 'ルミニアン「アーン」の独立構造体。\n光を放つ微粒子が、表面から放出されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1787, 'ペミデ器官', 'ルミニアン「ペミデ」の独立構造体。\n光を放つ微粒子が、表面から放出されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1788, 'ヨヴラ器官', 'ルミニアン「ヨヴラ」の独立構造体。\n光を放つ微粒子が、表面から放出されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1789, 'チョコボ試乗券', 'チョコボ厩舎が乗鳥初心者のために発行した\n短時間の無料乗鳥券。');
