INSERT INTO japanese_item (itemid, name, description) VALUES (1813, '銀朱', '東方の製法による朱色の塗料。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1814, '斉天朱', 'アニマによって調合された、鮮やかな銀朱。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1815, '聖木', 'アニマによって耐性を強めた神代木。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1816, '真龍角', '真龍の見事な角。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1817, '覇王樹の子株', 'アルテパ砂漠原産のサボテンの子株。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1818, 'ユブヒ器官', 'ルミニアン「ユブヒ」の独立構造体。\n光を放つ微粒子が、表面から放出されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1819, 'ルミニオンチップ', 'ルミニオンの構造素材の断片。\nとても軽く、研磨されたように表面は滑らか。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1820, '作戦書：防戦', 'フェローへの作戦指示が記された羊皮紙。\n防御に重点を置いた作戦の要綱が記述されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1821, '金剛不壊の証', '楯の達人であることを証明するパピルス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1822, '神楯の欠片', '禁断の楯の一部。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1823, '海老灯篭船', '海老をモチーフにしたブリキの玩具。\n背皿のロウソクを灯すと、蒸気の力で水面を走る。\n尻尾の先端がひょこひょこ動くギミックがある。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1824, 'ゴーストムレタ', 'ただならぬ霊気を放つ闘羊用の布。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1825, 'アントリオトラップ', 'アンティカが考案した強力なアントリオン用猟具。\nアントリオン自身の顎を主な材料としているため\n彼らの鋭い嗅覚を誤魔化すことができる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1826, '五色の糸', '見る角度によって異なる色に見える不思議な糸。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1827, 'プレミアムバッグ', '豪華な材料で製作されたハンドバッグ。\nスタイル重視の作りで、ほとんど何も収納できず\n実用性に乏しいがステータスアイテムとして有名。');
