INSERT INTO japanese_item (itemid, name, description) VALUES (1829, '赤草布', '赤草糸を編んで作った布。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1830, '沙蚕培養砂', 'ゴカイが生育し易いよう成分調整された砂。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1831, '蚯蚓培養土', 'リトルワームが生育し易いよう成分調整された土。\n');
