INSERT INTO japanese_item (itemid, name, description) VALUES (1837, '剣の枝', '剣のように先端が鋭利に尖った、よくしなう枝。\n微かに血の臭いがする。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1838, 'バル貝の殻', 'アクセサリに用いられる美しい模様の貝殻。\n');
