INSERT INTO japanese_item (itemid, name, description) VALUES (1842, '祈雨石', '東方で雨乞いの祈祷に用いられている石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1843, '赤霊布', '挑発的な霊気を放つ真赤な布。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1844, '黄霊布', '穏やかな霊気を放つ黄色い布。\n');
