INSERT INTO japanese_item (itemid, name, description) VALUES (1846, 'プミミちゃん', 'タルタルの魔法少女をモチーフにした女児用玩具。\nニュモモちゃんの妹で、三姉妹の次女。\nおっとりしているけれど夢は彫金師という設定。');
