INSERT INTO japanese_item (itemid, name, description) VALUES (1861, '錦綿羊の毛皮', 'カールした綿毛が美しい大羊の毛皮。\nモブリンが地底飼育用に品種改良した羊のもの。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1862, '錦綿羊のなめし革', '薄くて丈夫な錦綿羊のなめし革。\n');
