INSERT INTO japanese_item (itemid, name, description) VALUES (1866, 'クゥダフ冑パーツ', 'クゥダフに扮する冑製作のために加工された甲羅。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1867, 'ヤグード頭衣シート', 'ヤグードに扮する頭衣製作のために裁断された布。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1868, 'ゴブリン頭巾シート', 'ゴブリンに扮する頭巾製作のために裁断された革。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1869, 'ラミアの抜け殻', '脱皮したラミアの皮。\n絹のような肌触りで、高値で取り引きされている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1870, '無痴の善根', '記録をわずかにとどめた「光り輝くもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1871, '上質なペミデ器官', '状態のよい「ペミデ」の独立構造体。\n光を放つ無数の微粒子が表面から放出されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1872, 'ゴラホＭチップ', 'ルミニオン「ゴラホ」の独立構造体。\n中を覗くと、星のように瞬く無数の光が見える。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1873, '山師の海図', '山師の記したらしい海図の入った硝子瓶。\n図にはブブリム半島のクーンタ砂浜に\n印がつけられている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1874, '海賊の海図', '海賊の記したらしい海図の入った硝子瓶。\n図にはバルクルム砂丘の白骨砂浜に\n印がつけられている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1875, '獣人古銭', 'かつてクゥダフが鋳造していた金貨。\n現在の金貨より金の含有率が高く、純金に近い。\n中心にはダイアモンドが埋め込まれている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1876, '作戦書：持久戦', 'フェローへの作戦指示が記された羊皮紙。\n回復に重点を置いた作戦の要綱が記述されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1877, 'フォモルコデックス', '全頁びっしりとフォモル文字が記された写本。\n彼らの奪われた歴史が綴られているという。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1878, 'エアタンク', 'ブラス板で作られた気体用の密閉容器。\n新鮮な空気が詰まっている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1879, '再生の白金', 'アニマによって再生効果を得た白金の塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1880, 'クラスタードタール', 'クラスターが稀に産する粘性の強い黒色の液体。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1881, 'シールドバグ', '上から見た形状がカイトシールドに似ている虫。\nうっかり触れると猛烈な悪臭を放つ。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1882, '亜麻仁油', '亜麻の種子から搾りだされた黄色の油。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1883, '胡粉', '貝殻を粉砕して精製された白色の粉末。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1884, '亜鉛華', '亜鉛を燃焼して精製された白色の粉末。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1885, '紅亜鉛鉱', '地底で結晶化した天然の亜鉛華。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1886, 'ジーグリンデパテ', '錬金術師ジーグリンデが開発した接着・充填剤。\nガラスの枠止めの他\n割れ目や継ぎ目を埋め、防水処理等に用いられる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1887, 'ガラス板', '硝子の板。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1888, '珪砂', '石英粒を主とする褐色の砂。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1889, '白砂', '美しい光沢をもつ白色の砂。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1890, '増える水草', '生命力の強い水草を選び、瞬間冷却したもの。\n淡水につけると復活して繁茂する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1891, '増える海草', '生命力の強い海草を選び、瞬間冷却したもの。\n海水につけると復活して繁茂する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1892, '淡水の素', '水を天然の淡水に近い成分に調整する水溶粉末。\n錬金術ギルド製。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1893, '海水の素', '水を天然の海水に近い成分に調整する水溶粉末。\n錬金術ギルド製。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1894, '金魚水セット', '金魚を飼育するための人工環境生成キット。\n');
