INSERT INTO japanese_item (itemid, name, description) VALUES (1978, '血塗られた雄羊革', 'アニマによって血のような色に染まった雄羊の革。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1979, 'リーチの唾液', '血液の凝固を止める効果のあるリーチの唾液。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (1980, 'アンティカ酸', 'アンティカの毒腺で作られる刺激臭のある液体。\n行軍や補給ルートの道標として利用されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1981, 'スカルローカスト', '近年、サルタバルタを荒らしているイナゴ。\n頭にドクロのような不気味な模様があるが\n魔道士の悪戯によるもの、という説がある。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1982, 'キングローカスト', 'ギデアス周辺に生息するバッタ。\n飛び立つ時、ワハハと笑い声のような音を発する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1983, 'マッシュローカスト', 'エルシモ島の森林に適応したササキリ。\n風変わりな食性でキノコ類を主食としている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1984, 'スナッピングモール', 'グスタベルグに生息する小型のモグラ。\n狂暴で、鉱山労働者がよく足に噛み付かれる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1985, 'ヘルムモール', '陸棲珊瑚を住処とする奇妙なモグラ。\n泥除けの冑のような硬い殻で頭が覆われている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1986, 'オーキッドチップ', '半透明な淡紫色の小さな六角形の板。\n中を覗くと、瞬く無数のラインが見える。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1987, 'チャコールチップ', '半透明な消炭色の小さな六角形の板。\n中を覗くと、瞬く無数のラインが見える。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1988, 'マゼンタチップ', '半透明な赤紫色の小さな六角形の板。\n中を覗くと、瞬く無数のラインが見える。');
INSERT INTO japanese_item (itemid, name, description) VALUES (1989, 'ダークブロンズ', '製錬した黒青銅の塊。\n');
