INSERT INTO japanese_item (itemid, name, description) VALUES (2122, 'オビンニクの革', 'とても強靭なオビンニクのなめし革。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2123, 'カトブレパスの毛皮', 'とてもごわごわしたカトブレパスの毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2124, 'カトブレパスの革', 'とても丈夫なカトブレパスのなめし革。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2125, 'イエロームートン', '毛を刈りそろえて黄色く染色した羊のなめし革。\n肌触りがよく、耐熱性に優れる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2126, 'オーピメント', '有毒の黄色い鉱物。\nてらてらとした光沢がある。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2127, 'メタルチップ', '金属質の小さな六角形の板。\n中を覗くと、瞬く無数のラインが見える。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2128, 'スピンドル', '織工ギルドで糸を紡ぐため使用される紡錘。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2129, 'タンニングバット', '革工ギルドで革をなめすため使用される桶。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2130, '鮫やすり', '骨工ギルドで矢尻を磨くため使用されるやすり。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2131, 'トリチャレーター', '錬金術ギルドで薬を磨り潰すため使用される乳鉢。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2132, '魔力の楊柳', 'アニマによって魔力が顕在化したウィロー材。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2133, '魔力の山栗', 'アニマによって魔力が顕在化したチェスナット材。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2134, '雷光鉄', 'アニマによって雷光をまとった鉄の塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2135, '雷光鋼', 'アニマによって雷光をまとった鋼の塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2136, '勇力の紅縞瑪瑙', 'アニマによって力強い輝きを得たサードニクス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2137, '視力の紫水晶', 'アニマによって透明度の増したアメジスト。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2138, '魔魅の木綿布', 'アニマによって魔を魅了する色に染まった木綿布。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2139, '香るダルメル毛皮', 'アニマによって奇妙な香りを放つダルメルの毛皮。\n');
