INSERT INTO japanese_item (itemid, name, description) VALUES (2141, '嘆きの骨くず', 'アニマによって魔法を定着し易くした生物の骨片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2142, '嘆きの雄羊の角', 'アニマによって魔法を定着し易くした雄羊の角。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2143, 'マンドレル', '鍛冶・彫金ギルドで鎖を作るため使用される心金。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2144, '工業用アンビル', '鍛冶・彫金ギルドで金属板を作るため使用される\n使い捨ての鉄床。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2145, '風糸', '織工ギルドで矢羽根を形成するため使用される糸。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2146, 'メローの鱗', '柔軟で美しいメローのウロコ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2147, 'マーリドの牙', '近東で至高の骨材とされる巨獣の門歯。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2148, 'プークの翅', '軽量で透明な合成獣の羽根。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2149, 'アプカルの羽根', 'アプカルの翼に生えている水切羽。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2150, 'コリブリの尾羽根', 'コリブリの尾に生えている羽根。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2151, 'マーリドの毛皮', 'ごわごわしたマーリドの毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2152, 'マーリドのなめし革', 'とても分厚く丈夫なマーリドのなめし革。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2153, 'キキルンの砂袋', 'キキルンが緊急避難用に携帯している砂入りの袋。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2154, 'オロボンのランプ', 'オロボンの発光器官。\n怪しい光で魅惑し、餌となる魚を引き寄せる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2155, 'レッサーチゴー', '近東の寄生虫チゴーの小型種。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2156, 'アトルガン茶葉', 'アトルガンで栽培されている超高級茶葉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2157, 'インプの角笛', 'インプが連絡用に携帯している角笛。\n本人しか吹けないよう邪悪な呪紋が施されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2158, 'ハイドラの牙', 'ハイドラの長大な毒牙。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2159, 'クトゥルブの包帯', 'クトゥルブの全身を覆っていた防腐帯。\n様々な防腐剤や乳液が染み込んでいる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2160, 'トロールの肩甲', 'トロールの軽戦士が肩に着用する青銅のよろい。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2161, 'トロールの腕甲', 'トロールの重戦士が前腕に着用する青銅のよろい。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2162, 'マムージャの冑', 'マムージャの戦士が着用する鉄のかぶと。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2163, 'インプの翼', 'インプから切り取られた小さな翼。\n生命力が強く、切断後もバタバタ動き続ける。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2164, 'ペプレドの巣の欠片', 'ペプレド蜂の分泌物でできた巣の欠片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2165, 'クトゥルブの首飾り', 'クトゥルブの首を飾っていたネックレス。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2166, 'マーリドのたてがみ', '長く丈夫なマーリドのたてがみ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2167, 'ラミアの腕輪', 'ラミアの前腕を飾っていた黄金の腕輪。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2168, 'ケルベロスの爪', '禍々しい妖気を放つケルベロスの爪。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2169, 'ケルベロスの皮', '禍々しい妖気を放つケルベロスの皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2170, 'ケルベロスなめし革', '僅かに熱を帯びているケルベロスのなめし革。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2171, 'コリブリの嘴', '大きく湾曲したコリブリのくちばし。\n非常に硬く、巣を狙う者の頭蓋骨をも穿つという。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2172, 'ハイドラの鱗', '分厚く弾力性に富むハイドラのウロコ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2173, 'ワモーラの繭', 'ワモーラの幼虫が作るマユの一部。\nワモーラ糸の原料となる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2174, '古鏡', '蛮族が掘り起こした古の魔鏡。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2175, 'フランの肉', '悪臭を放つ、ゲル状のフラン族の肉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2176, 'ファイアカード', '特殊な製法で火の力を封じたゲームカード。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2177, 'アイスカード', '特殊な製法で氷の力を封じたゲームカード。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2178, 'ウィンドカード', '特殊な製法で風の力を封じたゲームカード。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2179, 'アースカード', '特殊な製法で地の力を封じたゲームカード。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2180, 'サンダーカード', '特殊な製法で雷の力を封じたゲームカード。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2181, 'ウォータカード', '特殊な製法で水の力を封じたゲームカード。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2182, 'ライトカード', '特殊な製法で光の力を封じたゲームカード。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2183, 'ダークカード', '特殊な製法で闇の力を封じたゲームカード。\n');
