INSERT INTO japanese_item (itemid, name, description) VALUES (2306, '舞刀会の招待状', '謎の会合へと誘う書状。\n裏面にはサンドリア・バストゥーク・ウィンダス、\nそしてタブナジアの国章が記されている。');
