INSERT INTO japanese_item (itemid, name, description) VALUES (2308, 'ミスリルコイル', '螺旋状に形成した霊銀。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2309, 'ホムンクルス脊髄', '錬金術釜でのみ生成可能な人造生物の神経束。\n近東の秘術による産物。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2310, '人工血髄油', '天然の成分に似せて、配合された血髄油。\nオートマトンの体内を流れ、血液の役割を果たす。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2311, 'ミスリルギア', '霊銀の歯車で作られた動力伝導装置。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2312, 'チョコボの卵', '厚い殻に覆われた、大きなチョコボの卵。\nほんのり温かい。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2313, 'VCSチョコボ登録証', 'VCSがチョコボの登録を証明して交付する文書。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2314, 'チョコボの卵', '厚い殻に覆われた、大きなチョコボの卵。\nほんわか温かい。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2315, 'カラクール羊毛', 'カラクール大羊から刈り取った毛の束。\nカラクール毛糸の原料となる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2316, 'ポリフランペーパー', '紙状に薄く形成したポリフラン。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2317, 'チョコボの卵', '厚い殻に覆われた、大きなチョコボの卵。\nわずかに温かい。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2318, 'チョコボの卵', '厚い殻に覆われた、大きなチョコボの卵。\nいささか温かい。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2319, 'チョコボの卵', '厚い殻に覆われた、大きなチョコボの卵。\nちょっぴり温かい。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2320, 'ミュココちゃん', 'タルタルの魔法少女をモチーフにした女児用玩具。\nニュモモちゃんの従妹の双子。\n呑気だけどかけっこが大好きという設定。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2321, 'リャココちゃん', 'タルタルの魔法少女をモチーフにした女児用玩具。\nニュモモちゃんの従妹の双子。\n短気だけど釣りが大好きという設定。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2322, 'アチューナー', '火の属性を秘めたオートマトンのアタッチメント。\n強い敵に対して、攻撃力アップの効果。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2323, 'Ｔ．プロセッサー', '氷の属性を秘めたオートマトンのアタッチメント。\n状況判断を短時間で行う。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2324, 'ドラムマガジン', '風の属性を秘めたオートマトンのアタッチメント。\nすばやく遠隔攻撃を行う。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2325, 'イコライザー', '土の属性を秘めたオートマトンのアタッチメント。\nダメージが大きいほど、軽減率が増加する装甲。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2326, 'ターゲットマーカー', '雷の属性を秘めたオートマトンのアタッチメント。\n強い敵に対して、命中率アップの効果。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2327, 'マナチャネラー', '水の属性を秘めたオートマトンのアタッチメント。\n魔法使用間隔が長くなる代わりに、\n魔法攻撃力アップ。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2328, 'イレーザー', '光の属性を秘めたオートマトンのアタッチメント。\nライトマニューバの数に応じた\n弱体効果を消し去る。\nただし、ライトマニューバの負荷がかかる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2329, 'スモークスクリーン', '闇の属性を秘めたオートマトンのアタッチメント。\n命中率ダウン、回避率アップ。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2330, '与一の組緒', '伝説の弓取りの大鎧の一部と伝えられる美しい緒。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2331, '偉大な青魔道士の証', '偉大な青魔道士であることを証明するパピルス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2332, '偉大なコルセアの証', '偉大なコルセアであることを証明するパピルス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2333, '偉大な絡繰士の証', '偉大なからくり士であることを証明するパピルス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2334, 'ポロッゴハット', 'ポロッゴの着用する奇妙な形の帽子。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2335, 'ソウルフレア触手', 'ソウルフレアから切り取られた触手。\n生命力が強く、時々ピチピチと動く。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2336, 'ソウルフレアの杖', 'ソウルフレアが携帯しているワンド。\n本人しか振れないよう邪悪な呪紋が施されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2337, 'ワモーラの毛', 'ワモーラの成虫から刈り取った体毛の束。\nワモーラ糸の原料となる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2338, 'ワモーラの鱗粉', 'ワモーラの成虫の翅から採取したウロコ状の粉。\nキラキラと光を複雑に反射する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2339, 'VCS雄鳥診断書', 'VCSがチョコボの雄鳥に発行する健康診断書。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2340, 'アトルガン絹布', '近東風の織り方で織られた絹布。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2341, '測深儀', '雷鳴を発して、海底の起伏を測定・再現する装置。\nかつて、イフラマド王国の船舶に搭載されていた。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2342, 'VCS雌鳥診断書', 'VCSがチョコボの雌鳥に発行する健康診断書。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2343, 'ラテーヌミレット', 'ラテーヌ原産の粟。\nチョコボの飼料に配合される。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2344, 'VCSハネムーン旅券', 'VCSがチョコボのカップルに贈る半日放牧券。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2345, 'ハイチョコエリクサ', 'チョコボ用に調合された高級エリクサー。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2346, 'トルネードサラダ', 'チョコボ用に調理された超豪華なサラダ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2347, 'Ｒ．シールド', '火の属性を秘めたオートマトンのアタッチメント。\n「ブレイズスパイク」を使用する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2348, 'トランキライザー', '氷の属性を秘めたオートマトンのアタッチメント。\n魔法命中率アップの効果。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2349, 'ターボチャージャー', '風の属性を秘めたオートマトンのアタッチメント。\nヘイストの効果。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2350, 'シュルツン', '土の属性を秘めたオートマトンのアタッチメント。\n物理攻撃による大ダメージをアースマニューバの\n効果をひとつ消して軽減することがある。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2351, 'ダイナモ', '雷の属性を秘めたオートマトンのアタッチメント。\nクリティカルヒット確率アップの効果。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2352, 'コンデンサー', '水の属性を秘めたオートマトンのアタッチメント。\nウォータマニューバの効果をひとつ消して、\nオーバーロードを防ぐことがある。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2353, 'Ｏ．ファイバー', '光の属性を秘めたオートマトンのアタッチメント。\n他のアタッチメントの性能アップの効果。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2354, 'エコノマイザー', '闇の属性を秘めたオートマトンのアタッチメント。\nMPが少ないとき、ダークマニューバの数に\n応じたMPを回復することがある。\nただし、ダークマニューバの負荷がかかる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2355, 'ジャジャの胸甲', 'グルージャジャが着用していた胸甲。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2356, 'グーフールーの冑', 'トロールの傭兵団長が着用していた冑。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2357, 'メドゥーサの腕輪', 'メドゥーサの前腕を飾っていた腕輪。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2358, '金石の飛竜鱗', 'アニマによって硬度の増したワイバーンの鱗。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2359, 'スターサファイア', '幸福の星彩が美しく輝く最高級のサファイア。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2360, 'ゴールドギア', '黄金の歯車で作られた動力伝導装置。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2361, 'アムルタートのつる', 'アムルタートから切り取られたつる。\n生命力が強く、時々ウネウネと獲物を求めて動く。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2362, 'ハイエボナイト', '高品質のエボナイト合成樹脂。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2363, '煉瓦', '粘土に砂や石灰などを混ぜて焼き固めた建築材料。\n耐熱性に優れる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2364, 'イエロージンセン', '黄色い色をした薬用人参。\n滋養強壮の効能がある。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2365, '悪魔の血', 'デーモン類のものと思われる血液。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2366, 'ホイッスル交換券', 'VCS発行「チョコボホイッスル」の交換券。\n上級厩務員に中古品と共に渡すと、\n新品のホイッスルと交換してくれる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2367, 'ギサールスープ', '特殊な方法で配合された野菜汁。\nチョコボの飼料。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2368, 'デラックスカロット', '特殊な肥料で育てられた高級人参。\nチョコボの飼料。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2369, 'デラックスワーム', '特殊な飼料で育てられた高級環虫。\nチョコボの飼料。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2370, '花の種袋', '様々な花の種が入った袋。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2371, 'キマイラの角', '節くれ立ったキマイラの角。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2372, 'キマイラのたてがみ', '太く強靭なキマイラのたてがみ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2373, 'キマイラの尾', 'キマイラから切り取られた尾。\n独自に意思を持ち、蛇のようにウネウネと動く。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2374, '蛇毒素', '蛇毒薬の材料となる粉末。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2375, 'ゼオルムのカード', '「ゼオルム遺構」で入手した輝金製のカード。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2376, 'アラパゴのカード', '「アラパゴ遺構」で入手した輝金製のカード。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2377, 'バフラウのカード', '「バフラウ遺構」で入手した輝金製のカード。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2378, '銀海のカード', '「銀海遺構」で入手した輝金製のカード。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2379, 'チョコボカラー:黄', 'チョコボの羽色を黄色に染め上げるヘアダイ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2380, 'チョコボカラー:赤', 'チョコボの羽色を赤色に染め上げるヘアダイ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2381, 'チョコボカラー:青', 'チョコボの羽色を青色に染め上げるヘアダイ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2382, 'チョコボカラー:緑', 'チョコボの羽色を緑色に染め上げるヘアダイ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2383, 'チョコボカラー:黒', 'チョコボの羽色を黒色に染め上げるヘアダイ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2384, '青煙のフラスコ', '中に青い煙が充満しているフラスコ。\n「注意！超可燃性ガス」とラベルに書いてある。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2385, '朽ちた円盾', '巨人族ウラノス家のアルキオネウスが\n大切にしている、かつての好敵手の盾。\nかなり傷んでおり、装備することはできない。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2386, '古びた角笛', '巨人族ウラノス家のパラースが大切にしている\n古代龍の角から作られた角笛。\n長大で、人間が吹き鳴らすことはできない。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2387, '怪し火のランタン', '「僧都のログベリ」が大切にしているランタン。\n中で陰気な炎がちろちろと揺らめいている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2388, 'ダイオライト', '「ウルリクムミ」の一部とされる閃緑岩。\n雲母がキラキラと輝いている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2389, 'スピードアップル', '蜂蜜を塗ったリンゴ。\nレース中、チョコボの速度を一定時間上げる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2390, 'スタミナアップル', 'ヨーグルトを塗ったリンゴ。\nレース中、チョコボの体力消費を一定時間抑える。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2391, 'シャドウアップル', 'コーヒーを塗ったリンゴ。\nレース中、チョコボの回避力を一定時間上げる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2392, 'ペッパークッキー', '食べるとくしゃみが止まらないイタズラ用菓子。\nレース中に食べさせると……。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2393, 'ホットクッキー', '食べると辛くて口から火を吹くイタズラ用菓子。\nレース中に食べさせると……。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2394, 'ギサールクラッカー', '周囲に野菜の香りがプ～ンと漂うイタズラ用花火。\nレース中に鳴らすと……。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2395, 'マッシュクラッカー', 'ついつい踊ってしまう胞子を撒くイタズラ用花火。\nレース中に鳴らすと……。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2396, '照る照る坊主', '東方に伝わる晴天祈願用の人形。\nレース中に吊るすと……。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2397, '雨乞虫', '東方に伝わる雨天祈願の蛙。\nレース中に放すと……。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2398, 'チョコボバンデージ', '肢を保護し競争に全力を投じさせるチョコボ装具。\nレース中、チョコボの力が向上する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2399, 'チョコボブリンカー', '側面の視界を遮り競争に集中させるチョコボ装具。\nレース中、チョコボの持久力が向上する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2400, 'シャドウロール', '足下の視界を遮り競争に集中させるチョコボ装具。\nレース中、チョコボの判断力が向上する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2401, 'チョコボフード', '音を遮り競争に集中させるチョコボ装具。\nレース中、チョコボの感受性が向上する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2402, 'レース出走許可証', 'チョコボの出走を許可する証明書。VCS交付。\n「チョコボレース」に参加するために必要。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2403, '競走鳥ＳＴＲ特訓券', '力を重視した競争鳥用の特別訓練トークン。\nVCS発行。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2404, '競走鳥ＥＮＤ特訓券', '持久力を重視した競争鳥用の特別訓練トークン。\nVCS発行。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2405, '競走鳥ＤＳＣ特訓券', '判断力を重視した競争鳥用の特別訓練トークン。\nVCS発行。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2406, '競走鳥ＲＣＰ特訓券', '感受性を重視した競争鳥用の特別訓練トークン。\nVCS発行。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2407, '競走鳥普通訓練券', '競争鳥用の通常メニューの訓練トークン。\nVCS発行。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2408, 'フロコンドメル', '美しい乳白色の珊瑚の欠片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2409, 'フレイムホルダー', '火の属性を秘めたオートマトンのアタッチメント。\nウェポンスキル発動時、ファイアマニューバの数に応じた\nダメージアップ。\nただし、ファイアマニューバの負荷がかかる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2410, 'アイスメーカー', '氷の属性を秘めたオートマトンのアタッチメント。\n魔法詠唱時、アイスマニューバの数に応じた魔攻アップ。\nただし、アイスマニューバの負荷がかかる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2411, 'レプリケーター', '風の属性を秘めたオートマトンのアタッチメント。\nHPが減少している時、\nウィンドマニューバの数に応じた\n分身を作り出す。\nただし、ウィンドマニューバの負荷がかかる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2412, 'ハンマーミル', '土の属性を秘めたオートマトンのアタッチメント。\nシールドバッシュのダメージを増幅。\nスロウの追加効果が発生することがある。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2413, 'コイラー', '雷の属性を秘めたオートマトンのアタッチメント。\n近接攻撃を連続で行うことがある。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2414, 'スチームジャケット', '水の属性を秘めたオートマトンのアタッチメント。\n直前に受けたダメージと同じ属性のダメージを\n軽減する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2415, 'Ｔ．チャージャーII', '風の属性を秘めたオートマトンのアタッチメント。\nヘイストの効果。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2416, 'Ｖ．チューブII', '光の属性を秘めたオートマトンのアタッチメント。\nケアル回復量アップ。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2417, '鍮石', '天然の黄銅を含有する鉱石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2418, 'アトルガンブラス', '製錬した鍮石の塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2419, 'アトルガンブラス板', '鍮石の板。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2420, '紫電陸ガニ甲殻', 'アニマによって荷電された陸ガニの甲殻。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2421, '岩乗甲羅', 'アニマによって硬化された海亀の甲羅。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2422, 'メッシュミスリル板', 'アニマによって網目状に穴の開けられた霊銀の板。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2423, '凍寒ラプトル皮', 'アニマによって冷却されたラプトルの皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2424, '耐熱毛織物', 'アニマによって発火性と耐熱性を付与された織物。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2425, '濡れたビロード', 'アニマによって加湿したビロード。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2426, '鎧竜の角', '鎧竜「ウィヴル」の極太の角。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2427, '鎧竜の槌', '鎧竜「ウィヴル」の尾の先端。\n骨がハンマー状に形成されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2428, '鎧竜の装甲', '鎧竜「ウィヴル」の厚皮。\n剣を通さぬほど硬く分厚い。');
