INSERT INTO japanese_item (itemid, name, description) VALUES (2472, '冥感の鎖', '冥界の金属を溶かし込んで作られた鎖。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2473, '冥応の鎖', '冥界の金属を溶かし込んで作られた鎖。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2474, '冥助の鎖', '冥界の金属を溶かし込んで作られた鎖。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2475, 'カオリン', '陶磁器等の原料に用いられる高級粘土。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2476, '白金糸', '芯に白金を巻きこんだ絹糸。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2477, '封獣板', '魔獣の組織が貼り付けられた板。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2478, '魔獣鏡', '組織を手がかりにして魔獣を招き寄せる\n魔鏡を取り付けた封獣板。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2479, '勝鳥投票券', 'チョコボレースの競争鳥の着順を予想する投票券。\n的中したら配当を得ることができる。VCS発行。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2480, '封魄板', '魔物の魄の姿が焼き付けられた板。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2481, 'レース出走証明書', 'チョコボの出走を証明する文書。VCS発行。\n「チョコボレース」の賞金を受け取るために必要。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2482, '愛鳥ＳＴＲ特訓券', '力を重視した愛鳥用の特別訓練トークン。\nVCS発行。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2483, '愛鳥ＥＮＤ特訓券', '持久力を重視した愛鳥用の特別訓練トークン。\nVCS発行。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2484, '愛鳥ＤＳＣ特訓券', '判断力を重視した愛鳥用の特別訓練トークン。\nVCS発行。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2485, '愛鳥ＲＣＰ特訓券', '感受性を重視した愛鳥用の特別訓練トークン。\nVCS発行。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2486, 'チョココイン交換券', 'VCSで使用できるチョココインの引き換え券。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2487, '傭兵キャンプ参加券', '傭兵特訓施設「マーシナリキャンプ」の参加券。\nサラヒム社の社章の透かしが入っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2488, 'アレキサンドライト', '光源によって緑色や赤色に変化する稀少な宝石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2489, 'アレヴァトと龍', '近東の古典「アレヴァトと龍」の彩色写本。\n邪龍一族を捜す、少女剣士の冒険恋愛譚。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2490, '禁断の宝のカギ', '時の深淵にある宝箱のカギ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2491, 'ルジャワン雑記', 'パパルンから渡されたアサルト専用ダイアリー。\n「ルジャワン霊窟」での顛末を克明に記述\nできるよう、予め頁が割り振られている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2492, 'マムージャ戦記', 'パパルンから渡されたアサルト専用ダイアリー。\n「マムージャ兵訓練所」での顛末を克明に記述\nできるよう、予め頁が割り振られている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2493, 'レベロス探検記', 'パパルンから渡されたアサルト専用ダイアリー。\n「レベロス風穴」での顛末を克明に記述\nできるよう、予め頁が割り振られている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2494, 'ペリキア探訪記', 'パパルンから渡されたアサルト専用ダイアリー。\n「ペリキア」での顛末を克明に記述\nできるよう、予め頁が割り振られている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2495, 'イルルシ旅行記', 'パパルンから渡されたアサルト専用ダイアリー。\n「イルルシ環礁」での顛末を克明に記述\nできるよう、予め頁が割り振られている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2496, '古代獣の角', '古代の獣のものと思われる角。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2497, 'ククルカンの皮', '「ククルカン」の弾力性に富む粗皮。\n緩衝材として鎧の裏地に使われる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2498, 'ブリアレオスの腰紐', '伝説のギガース族「ブリアレオス」の身に着けていた腰紐。刃で容易に切れないほど強靭。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2499, '不消化尾羽', '「グラヴォイド」の体内から出てきた謎の羽根。\n消化されることなく形を保っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2500, '公式魔獣鏡', '「パンクラティオン」参加の認可を受けた魔獣鏡。\n裏面に獣の形をした焼印が捺されている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2501, 'パペットターバン黒', 'スコーピオータイプのオートマトン用ターバン。\n黒魔法強化型。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2502, 'パペットターバン白', 'スコーピオータイプのオートマトン用ターバン。\n白魔法強化型。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2503, 'アーモンド', 'アーモンドの樹から採取された種。\n近東原産。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2504, 'クゥダフの超重胸甲', 'クゥダフが胸に着用する重装甲のよろい。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2505, 'クゥダフの超重背甲', 'クゥダフが背に着用する重装甲のよろい。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2506, 'レディバグの上翅', '赤地に黒紋が印象的な「レディバグ」の硬い羽根。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2507, 'リコポディウムの花', '「リコポディウム」の頭頂に咲く真紅の開放花。\n');
