INSERT INTO japanese_item (itemid, name, description) VALUES (2515, 'サンドウォームの牙', '「サンドウォーム」の口角に生える鋭い歯。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2516, 'サンドウォームの殻', '「サンドウォーム」の背面を守る硬質の殻。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2517, '.', '.');
INSERT INTO japanese_item (itemid, name, description) VALUES (2518, 'スミロドンの毛皮', '縞の鮮やかな剣虎「スミロドン」の毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2519, 'ヤグードの大袖', 'ヤグードが着用する東方様の肩甲。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2520, 'ヤグードの篭手', 'ヤグードが着用する東方様の篭手。\n人間には装備不可能。');
