INSERT INTO japanese_item (itemid, name, description) VALUES (2858, 'ウォルフラム鋼', '非常に硬度の高い鋼の一種。\n失われた製法により精錬された。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2859, 'コバルト鉱', '貴金属のコバルトを含有する鉱石。\n加工の際に不純物として扱われることで\n美しい青色を呈する。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2860, '石墨', '炭素からなる黒色の鉱物。\n雷のエネルギーとの相性が良いことでも知られる。');
