INSERT INTO japanese_item (itemid, name, description) VALUES (2874, '蛍光鱗粉', 'ピクシー族の羽根から得た淡い光を放つ鱗粉。\n特殊な薬品と混合することで治癒効果を発揮する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2875, '妖蟲の鱗粉', 'ピクシー族の羽根から得た鱗粉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2876, 'ねばねばした金塊', '粘液でねばねばしている金の塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2877, '不浄なる白銀', '魔物の不浄な力で汚れ、その輝きを失った銀の塊。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2878, '緋のカディーフェ', '血に染まったような緋色をしているが、\n肌触りのよい布。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2879, 'バーナクルシャード', 'クラブ族「クラブカタウ」の隆起した甲殻から\n剥離した欠片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2880, 'キドニーストーン', 'アントリオン族「オルクス」の体内から出てきた\n小石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2881, 'ヴェルザンディアイ', 'ピクシー族「ヴェルザンディ」が身に着けていた\n装飾品についていた宝石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2882, 'メガクロット', '巨大なクロット「ブロブディンナグ」の\n小型の分身。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2883, 'ルスベンの指爪', 'ヴァンピール族「ルスベン」の鋭い指爪。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2884, 'クラブカタウの甲殻', 'クラブ族「クラブカタウ」の甲殻。\n通常のクラブ族のものよりも硬質性に優れる。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2885, 'オルクスの大顎', 'アントリオン族「オルクス」の巨大なアゴ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2886, '朽ちた鋳塊', '腐食が進み、朽ち果てた金属の塊。\nもはや何の金属か分からない。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2887, '崩れた鋳塊', 'ひび割れ、ぼろぼろになった金属の塊。\nもはや何の金属か分からない。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2888, 'サングイニス', '「ヴォラジアン」の体表面にみられる組織。\n生命活動の終息とともに小さな亀裂が入るが、\n血のように赤い美しさは保たれている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2889, 'リミュルの鋏脚', 'リミュルの脚の一部。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2890, 'クリオニッドの翼足', 'クリオニッドの翼足の一部。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2891, '乾燥チゴー', '干乾びたチゴーの死骸。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2892, '大羊の羶肉', 'とても生臭い大羊の肉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2893, '肥大した黒虎の牙', '異常に伸びた黒虎の犬歯。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2894, '戦勝の盾', 'ギガースが腰に吊るしている盾。\n元は勝利し、認めた人間の持ち物。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2895, '大型靴下', '特に大きなギガースの靴下。\n長期間履き続けたため強烈な臭いがする。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2896, '超重量腕輪', 'とても重いギガースの腕輪。\n一説にはギガースの鍛錬のひとつだと云う。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2897, '透通った虫の翅', '日に翳すと見えなくなるくらい透通った虫の翅。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2898, '黒色鱗粉', '光を吸収する性質のある鱗粉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2899, 'プークの寒卵', '特に栄養のあるプークの卵。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2900, '虫食いハット', '小さな穴のあいたポロッゴハット。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2901, '天然アガリクス', '大きく育ったアガリクス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2902, 'ノールの黒爪', 'とりわけ汚いノールの鉤爪。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2903, 'エフトの血', 'リーチ族にもあまり好まれないエフトの血液。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2904, '長大なスラッグの眼', '異常に長いスラッグの眼。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2905, '月光布', '月光下でのみ発光するアストラル物質の布。\n非常にもろく、加工は不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2906, '朽ちかけの球根', '朽ちかけているトレントの球根。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2907, 'ミニモルボルのつる', '小さなモルボルのつる。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2908, 'ウツツタケ', '食べると我を忘れてしまうといわれるキノコ。\n食用には適さない。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2909, '蛇苔', 'グゥーブーの背に寄生する珍しい苔。\n蛇の体表のように見える。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2910, '鎧竜の尖角', '鋭く尖ったウィヴルの角。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2911, 'ちぎれたエフトの皮', 'ちぎれたエフトの皮の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2912, '巨大なブガードの牙', '特に大きなブガードの牙。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2913, '曇ったレンズ', '曇ってしまったアーリマンのレンズ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2914, 'せぜらきの魂', '水生生物の魂と云われる小さな塊。\nそっと耳に近づけるとせぜらきが聞こえる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2915, '上質な翼足', '状態のよいクリオニッドの翼足。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2916, '上質な鋏脚', '状態のよいリミュルの鋏脚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2917, 'ヘクトアイズの赤眼', '充血しているヘクトアイズの眼球。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2918, '禍々しい頭骨', '呪いを振りまくコープスライトの頭骨。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2919, '血のついた牙', '新しい血の付いているコウモリの牙。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2920, 'アルカリ腐葉土', 'アルカリ性が強く通常の栽培には適さない腐葉土。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2921, '猛毒サソリの針', '特に毒性の強い大サソリの針。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2922, 'エフトの卵', '美味で知られるエフトの卵。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2923, 'コカトリスの尾肉', '淡味で知られるコカトリスの尾の肉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2924, 'しびれる上髭', 'クァールから切り取られたヒゲ。\n帯電しておりビリビリとしびれる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2925, '強靭なたてがみ', '特に弾力のあるマンティコアのたてがみ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2926, '嘆くものの残滓', '「嘆くもの」の断片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2927, 'グラヴォイドの殻', '「グラヴォイド」の巨大な殻。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2928, 'クロリスの双葉', '「クロリス」の頭に生えている巨大な芽。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2929, 'ブリアレオスヘルム', '伝説のギガース族「ブリアレオス」が着用していた冑。人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2930, 'カラボスの小石', '「カラボス」が持っていた小さな宝石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2931, 'フィスチュルの体液', '「フィスチュル」から抽出した体液。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2932, 'ククルカンの毒針', '「ククルカン」の巨大な毒棘。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2933, 'チュクワの卵', '巨亀「チュクワ」の卵。\n通常のアダマンタスの卵に比べて明らかに大きい。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2934, 'マナナンガルの首飾', '「マナナンガル」の大きなネックレス。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2935, 'マーヴィンの毛皮', 'ウサギ族「古尾のマーヴィン」の毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2936, 'カズミックニードル', '「カズミックホーネット」から切り取られた針。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2937, 'ラスコヴニクのつる', '「ラスコヴニク」の巨大なつる。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2938, 'バッカの翼', 'インプ族「バッカ」から切り取られた翼。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2939, 'クエレブレの角', '「クエレブレ」の見事な角。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2940, 'ミクトランの法衣', '「ミクトランテクトリ」が着用していた衣。\n人間には装備不可能。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2941, 'キーシャのパママ', 'オポオポ族「キーシャポッポ」が持っていた\nパママ。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2942, 'マイキーの銀鉱', 'ワーム族「大口のマイキー」の飲み込んでいた\n大きな銀鉱。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2943, 'バラウルの頭骨', 'ワイバーン族「バラウル」の頭骨。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2944, 'リージェのランタン', '「リージェ」が持っていたランタン。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2945, '萎れた翼足', '乾燥し萎れてしまったクリオニッドの翼足。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2946, '萎れた鋏脚', '乾燥し萎れてしまったリミュルの鋏脚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2947, '鎮められた頭骨', '呪いの鎮められたコープスライトの頭骨。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2948, '酸性腐葉土', '弱酸性の栽培に適した腐葉土。\n');
