INSERT INTO japanese_item (itemid, name, description) VALUES (2950, 'ふさふさの上髭', '帯電質が抜けてふさふさになったクァールの髭。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2951, '孔雀石', '美しい緑色の鉱物。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2952, '封煙薬', '瘴気を一時的に中和する薬剤。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2953, '接着粘液', '蜘蛛の吐き出した粘液。\n接着剤の替わりに使われるほど強力。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2954, '火薬箱', '火薬の入った小型の箱。\n水底に沈んでいたため、今も使えるかは不明。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2955, '魔人印章', '闇の血族が用いると伝えられる印影。\n一部の上位階級の血族が所有する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2956, '魔王印章', '闇の血族が用いると伝えられる印影。\n貴族階級の血族により受け継がれてきた\n貴重なもの。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2957, '魔神印章', '闇の血族が用いると伝えられる印影。\n公爵階級の血族により受け継がれてきた\n貴重なもの。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2958, 'クーポンW-E85', 'モグハウス管理組合発行の引換券。\n様々な品と交換できる。\n引換アイテム：エンピリアンウェポン（Lv85）');
INSERT INTO japanese_item (itemid, name, description) VALUES (2959, 'クーポンA-RJob', 'モグハウス管理組合発行の引換券。\n様々な品と交換できる。\n引換アイテム：ジョブ専用アクセサリ（デュナミス）');
INSERT INTO japanese_item (itemid, name, description) VALUES (2960, '睡蓮', '薄紫色のスイレンの花。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2961, '血染めの毒針', '多くの獲物を突き倒し、芯まで血紅色に染まったペイストの毒棘。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2962, 'イツパパの鱗粉', '「イツパパロツル」の翅から採取した鱗粉。\nその独特の色から黒曜の輝きとも云われる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2963, 'ウルハドシの牙', '「ウルハドシ」の口角に生えていた鋭い歯。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2964, 'ソベクの皮', '巨大なブガード族「ソベク」の皮。\n小山の如き大瘤でゴツゴツしている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2965, 'キレインのランプ', '巨大魚「キレイン・キロイン」の発光器官。\n時に眩いほどの光で魅惑し、餌となる魚を引き寄せる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2966, 'ブッキスの翼', 'ファルシタウルス「ブッキス」の巨大な翼。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (2967, 'セドナの大牙', 'ルスゾル族「セドナ」の巨大な犬歯。\n大型の氷をも一撃で砕く。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2968, '暁の幽魂', 'アビセアに果てた魂の断片。\n明けの頃、仄かに光る。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2969, '黄昏の幽魂', 'アビセアに果てた魂の断片。\n宵の頃、儚く光る。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2970, '木人', '忍び道具のひとつ。\n身替の術に用いられる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2971, '猪ノ札', '上級忍び道具のひとつ。\n六つの遁術すべてに用いられる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2972, '鹿ノ札', '上級忍び道具のひとつ。\n己を強める術に用いられる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (2973, '蝶ノ札', '上級忍び道具のひとつ。\n敵を貶める術に用いられる。');
