INSERT INTO japanese_item (itemid, name, description) VALUES (3230, 'タブリーラ水銀', 'ドール族「タブリーラ」から採取された液体金属。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3231, 'シャラブハの毛皮', 'マンティコア族「シャラブハ」の毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3232, '虎王の毛皮', 'スミロドン「アンシェレク」の毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3233, 'ヴァドレアニの体液', 'レディバグ族「ヴァドレアニ」から採取された体液。\n強烈な苦みで天敵から身を守っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (3234, 'オアシスの水', 'パキポディウム「ブグル・ノッズ」が持っていた水。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3235, '砂まみれの破片', '破壊されたドールから採取された砂まみれの破片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3236, '燃えさかるうで', 'いまだ火の消えないボムのうで。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3237, '埋もれた牙', '砂に埋もれたマンティコアの犬歯。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3238, '上質なダルメル毛皮', '状態のよいダルメルの毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3239, '傀儡の血', '合成獣プークの血液。\n口にしたものは操り人形のように踊り続けるという。');
INSERT INTO japanese_item (itemid, name, description) VALUES (3240, '上質なコカトリス皮', '状態のよいコカトリスの皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3241, '紅娘の葉', 'レディバグに付着していた葉の一部。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3242, '上質な大サソリの爪', '状態のよい大サソリの爪。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3243, '砂漠の土', '砂が多く養分の少ない土。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3244, '巨樹の宿木', '寄生した大木を枯らすほどに育った木の枝。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3245, 'ベベルギア', 'アクロリス族「コガトゥ」の動力伝達に用いられる黄金の歯車。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3246, '雪神の魂', '巨大なスノール族「ウパシカムイ」の凍える魂。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3247, 'シーシュポスの破片', 'ゴーレム族「シーシュポス」から採取された破片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3248, '氷霧の翼', '放たれる風が氷のように冷たいという、\nインプ族「ホウィッティ」の翼。');
INSERT INTO japanese_item (itemid, name, description) VALUES (3249, 'アウズンブラの毛皮', 'バッファロー族「アウズンブラ」の毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3250, 'ヘリカルギア', 'アクロリスの動力伝達に用いられる霊銀の歯車。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3251, '不凍液', '寒冷地でも凍ることのないギア族の体液。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3252, '凍えるうで', '肌をさす冷気が漂ってくるスノールのうで。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3253, '上質なマーリド毛皮', '状態のよいマーリドの毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3254, '氷竜の鱗', '氷のように冷たいワイバーンのウロコ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3255, '白蚯蚓の土', 'エントゾアンが排出した栄養価に優れた土。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3256, '斥候の号笛', 'インプの斥候が連絡用に携帯している角笛。\n通常のものよりも小型。');
INSERT INTO japanese_item (itemid, name, description) VALUES (3257, 'ぼやけた眼', '水晶のような結晶質のヴォドリガの眼。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3258, '上質な野牛の角', '状態のよいバッファローの角。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3259, '上質な黒虎の毛皮', '状態のよい黒虎の毛皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3260, 'ミルストーンの破片', 'マジックポット族「ティーケッセルチェン」から採取された破片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3261, 'ミナルジャの頭骨', '飛竜には珍しく頑丈なミナルジャの頭骨。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3262, 'ジャキュルスの翅', '非常に軽量なピープーク「ジャキュルス」の羽根。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3263, '水精の髪', 'ピクシー族「ローレライ」の澄んだ毛髪。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3264, 'ゴブリット火薬', '「火薬頭のバーストロックス」が開発した、\nゴブリン式の火薬。');
INSERT INTO japanese_item (itemid, name, description) VALUES (3265, '泡立つ燃料', 'マジックポットから取り出された液体。\nきめの細かいクリーミーな泡が香ばしい。');
INSERT INTO japanese_item (itemid, name, description) VALUES (3266, '漆黒のうで', '不気味な黒炎に覆われたジンのうで。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3267, '森神の翼', 'アヤッタラから切り取られた巨大な翼。\n森に入る際のお守りとして珍重される。');
INSERT INTO japanese_item (itemid, name, description) VALUES (3268, '上質な鎧竜の装甲', '状態のよいウィヴルの厚皮。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3269, 'すり減った臼歯', 'ひどくすり減ったスケルトンの奥歯。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3270, '上質な陸魚の鱗', '状態のよい魚のウロコ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3271, '妖蟲の涙', 'ピクシーが持っていた小さな宝石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3272, '妖蟲の瞳', 'アンシーリーが持っていた小さな宝石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3273, 'ゴブリンロープ', 'ゴブリン特製の頑丈なひも。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (3274, 'ゴブリンオイル', 'ゴブリンが甲冑のさび止めに用いる油。\n');
