INSERT INTO japanese_item (itemid, name, description) VALUES (4041, 'ヨルシアビザジュV', '強い魔力を秘めている古い人形の頭のパーツ。\nスタチューセグメントと呼ばれ、\n東ウルブカ各地に散らばっている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4042, 'アクエフの鉱石', 'アクエフの体内で魔力を帯びた鉱石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4043, '溶岩の宝石', 'マグマの熱を帯びた宝石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4044, '水石墨', '炭素からなる黒色の鉱物。\n水の力で魔を退けると云われている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4045, '烈風の綿花', '風に運ばれた綿花。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4046, '腐食した鉱石', '毒の影響で赤く変色し、ボロボロになった石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4047, '丈夫な絹糸', 'ヨルシアに棲むエルカから採れる丈夫な絹糸。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4048, '竜眼', 'ウルブカ諸島に生息する美しい淡水魚。\n目の周りのコブが特徴で\nアドゥリンでは観賞用として珍重される。\n「グリーンサム・モーグリ」が興味を持っている\nようだが……。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4049, '錆びた銭', '海中から引き上げられた、錆びついた東方の通貨。\n「グリーンサム・モーグリ」が興味を持っている\nようだが……。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4050, '極太バローワーム', 'ミーブル族が好んで食べる極太のワーム。\n稀にしか捕れないため重宝されている。\n「グリーンサム・モーグリ」が興味を持っている\nようだが……。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4051, 'アロイトニック', '金属に吸収される不思議な液体。\n装備の秘められた力を引き出す。 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (4052, 'アロイトニック+1', '金属に吸収される不思議な液体。\n装備の秘められた力を大きく引き出す。 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (4053, 'アロイトニック+2', '金属に吸収される不思議な液体。\n装備の秘められた力をとても大きく引き出す。 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (4054, '黒甲虫の魂', '温かさを感じるクリスタルの塊。\n魔物の魂が宿っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4055, '黒砂蟲の魂', '温かさを感じるクリスタルの塊。\n魔物の魂が宿っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4056, 'パキポディウムの魂', '温かさを感じるクリスタルの塊。\n魔物の魂が宿っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4057, '氷晶石', '透明の宝石を含んでいることがある石。 \n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4058, 'ビスマス鉱', '金属の蒼鉛を含有する鉱石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4059, '深成岩', '長い年月を掛けて固まったマグマの岩石。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4060, '餅鉄', '希少な鉄の一種の金属を含有する鉱石。 \n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4061, 'リフトボウルダー', '狭間より現じた黒い玉石。 \n');
