INSERT INTO japanese_item (itemid, name, description) VALUES (4064, 'レム物語第一章', '全十章からなる物語の第一章。\n王の死から物語が始まる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4065, 'レム物語第二章', '全十章からなる物語の第二章。\n隣国との戦争が始まる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4066, 'レム物語第三章', '全十章からなる物語の第三章。\n戦争に敗北してしまう。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4067, 'レム物語第四章', '全十章からなる物語の第四章。\n王位を失脚し塔の地下に幽閉される。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4068, 'レム物語第五章', '全十章からなる物語の第五章。\n幽閉されて10年の歳月が経つ。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4069, 'レム物語第六章', '全十章からなる物語の第六章。\n11年目でレジスタンスが救出にくる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4070, 'レム物語第七章', '全十章からなる物語の第七章。\nレジスタンスの希望となる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4071, 'レム物語第八章', '全十章からなる物語の第八章。\nレジスタンスと王政の戦争が始まる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4072, 'レム物語第九章', '全十章からなる物語の第九章。\n民衆を味方につけ王政に勝利する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4073, 'レム物語終章', '全十章からなる物語の終章。\n失脚して13年後に王位に戻る。');
INSERT INTO japanese_item (itemid, name, description) VALUES (4074, '想うものの結晶', '「想うもの」の記憶の断片と\nわずかな生気が結晶化したもの。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4075, '願うものの結晶', '「願うもの」の記憶の断片と\nわずかな生気が結晶化したもの。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4076, '満たすものの結晶', '「満たすもの」の記憶の断片と\nわずかな生気が結晶化したもの。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4077, '月虹鋼', '醴泉島で製錬された玉鋼。\n月の光にあてると七色に光る。\n製錬する技法は失われている……。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4078, '月虹布', '醴泉島で織られた布。\n月の光にあてると七色に光る。\n織る技法は失われている……。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4079, '月虹革', '醴泉島で加工された革。\n月の光にあてると七色に光る。\n加工する技法は失われている……。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4080, '月虹漆', '醴泉島で作られた塗料。\n月の光にあてると七色に光る。\n作る技法は失われている……。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4081, '月虹石', '醴泉島で磨かれた宝石。\n月の光にあてると七色に光る。\n研磨する技法は失われている……。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4082, '月明の珊瑚', '醴泉島で生息していた珊瑚のかけら。\nやわらかい光を放っている。\n');
