INSERT INTO japanese_item (itemid, name, description) VALUES (4246, 'カンタレラ', '効果時間や効能を自在に調節できる、最強の毒薬。\nしかし、その取り扱いは大変難しく、\n調合者自らが命を落とすことも少なくない。');
