INSERT INTO japanese_item (itemid, name, description) VALUES (4249, 'シュルツの戦略論', '第二次コンシュタット会戦の勝利の立役者、\nグンサー・シュルツ参謀が著した戦略論文。\n共和国将官必読の書。\nLv65～ All Jobs');
