INSERT INTO japanese_item (itemid, name, description) VALUES (4270, '菱餅', '三枚重ねにした菱形のライスの固まり。\n各段の配色は各々異なる薬効を表すと云う。\nMP+17 VIT+2 INT+3 MND+1 回避+5\nレジストサイレス+4 ヒーリングHP+2\nヒーリングMP+2 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (4271, '粽', '竹の葉に包まれたライスの固まり。\n食した者の邪を払う魔除けの効能をもつと云う。\nHP+17 STR+3 VIT+2 AGI+1 命中+5\n攻+20% (最大45) 飛攻+30% (最大45)\nレジストパライズ+4 ヒーリングHP+2\nヒーリングMP+2');
INSERT INTO japanese_item (itemid, name, description) VALUES (4272, '龍の肉', '鮮度が落ちない、常にジューシーなドラゴンの肉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4273, 'キトロン', '酸味が強く栄養価が高い、伝説の果実。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (4274, 'ペルシコス', '果肉が軟らかく糖度が高い、伝説の果実。\n');
