INSERT INTO japanese_item (itemid, name, description) VALUES (4277, '殿様おにぎり', '珍味の入った高級おにぎり。\nHP+15 DEX+3 VIT+3 CHR+3\n真の味:攻+50 防+30 ダブルアタック+1%');
INSERT INTO japanese_item (itemid, name, description) VALUES (4278, '将軍おにぎり', '魂をこめて握られた殿様おにぎり。\nHP+20 DEX+4 VIT+4 CHR+4\n真の味:攻+50 防+30 ダブルアタック+2%');
