INSERT INTO japanese_item (itemid, name, description) VALUES (5109, '古い袋【緑霊石+1】', '『緑霊石+1』が入った小袋。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5110, '古い袋【緑霊石+2】', '『緑霊石+2』が入った小袋。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5111, '古い袋【白霊石+1】', '『白霊石+1』が入った小袋。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5112, '古い袋【白霊石+2】', '『白霊石+2』が入った小袋。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5113, '割れた木の実', 'ひび割れた硬い殻の木の実。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5114, '湿ったロランベリー', '蟲の唾液で防腐処理されたロランベリー。 \n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5115, '虫食いモコ草', '何かの蟲に食われて欠けているモコ草。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5116, 'ツイストワーム', '元気よくねじれて動いているワーム。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5117, 'ストーンパウダー', '粉末が体にまとわりついてくる不思議な石粉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5118, '小さなゴカイ', 'トード族が大好きな小さなゴカイ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5119, '訓練マニュアル', '厳しい訓練内容が記された本。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5120, 'タイタニックソー', '船を沈めると恐れられる、伝説の巨大海水魚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5121, 'ムーリシュアイドル', 'マリヤカレヤリーフに生息する、美しい海水魚。\nウィンダスでは観賞用として珍重される。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5122, 'ビビキースラッグ', 'ビビキー湾の浅海に生息する、極彩色の棘皮動物。\n食用だが、あまり美味しくない。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5123, 'ジャックナイフ', 'ビビキー湾の砂浜に生息する二枚貝。\n驚くと、ピョンッと巣穴から飛び上がる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5124, 'トロピカルクラム', 'ビビキー湾の砂浜に生息する二枚貝。\n非常に美味だが、個体数は少ない。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5125, 'ファノエニュート', 'ファノエ運河にのみ生息する緑色のイモリ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5126, 'マッディサイレドン', 'ファノエ運河に生息する小さなイモリ。\n水中に入ると、大きなエラが飛び出す。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5127, 'ググリューサウルス', '伝説の長大な海生ハ虫類。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5128, 'コーンカラマリ', '尖った殻が特徴的な頭足類。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5129, 'リク', '伝説の長大な淡水魚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5130, 'タブナジアゴビー', '旧タブナジア領の川底に生息する淡水魚。\n体色はオレンジとシルバーの鮮やかなストライプ。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5131, 'ボンゴラ', 'プルゴノルゴ島に生息する二枚貝の固有種。\nたいへん美味。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5132, 'ガーナード', 'ググリュー洋に生息する海水魚。\n短時間だが飛行できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5133, 'プテリゴートゥス', '「海のサソリ」と呼ばれる巨大節足動物。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5134, 'モラモラ', '遭難者を助けたという伝説もある巨大海水魚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5135, 'ライノキメラ', '剣のような吻を備えた巨大海水魚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5136, 'イスタヴリット', 'アラパゴ諸島の岩礁に生息する海水魚。\nヒレに猛毒を秘めている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5137, 'トゥルナバルウ', '時に水鳥や水辺の獣すら捕食する巨大淡水魚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5138, 'ブラックゴースト', '体内に発電器官をもつ淡水魚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5139, 'ベタ', '艶やかな美しさと強い闘争本能を備えた淡水魚。\n観賞魚として、あるいは闘魚として飼育される。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5140, 'カルカンバルウ', '「巨人の盾」と呼ばれる、伝説の巨大海水魚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5141, 'ヴェーダルラス', '伝説の提督の名を冠する、巨大海水魚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5142, 'バイソンステーキ', '厚切りで焼いた野牛の肉。\nSTR+6 AGI+1 INT-3 攻+18% (最大90)\n飛攻+18% (最大90) リザードキラー+5');
INSERT INTO japanese_item (itemid, name, description) VALUES (5143, 'ゴブリン風野菜炒め', 'ゴブリンがよく屋台等で売る、肉と野菜の炒め物。\n人間の口にも合うように調味されている。\nVIT+2 AGI+5 CHR-5');
INSERT INTO japanese_item (itemid, name, description) VALUES (5144, 'クリムゾンゼリー', 'クロットを型に容れ、ゼラチンで固めた菓子。\nMP+12% (最大85) INT+6 ヒーリングMP+2 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5145, 'フィッシュ＆チップ', '白身の魚と刻んだポポトイモの揚げ物セット。\nタブナジアの家庭料理。\nDEX+3 VIT+3 MND-3 飛命+7% (最大10) 防+5');
INSERT INTO japanese_item (itemid, name, description) VALUES (5146, 'ヘッジホッグパイ', '刻んだ肉を、豆入りパイ生地で包み焼きした料理。\n伝説の怪物「ヘッジホッグパイ」を模し、\n表面はカロットの針で飾られている。\nHP+55 STR+6 VIT+2 INT-3 MND+3 命中+5\n攻+18% (最大90) 飛攻+18% (最大90)\nヒーリングHP+2 ヒーリングMP+2');
INSERT INTO japanese_item (itemid, name, description) VALUES (5147, 'スノールジェラート', 'スノールの冷気で、ミルクを凍らせた氷菓子。\nMP+16% (最大75) ヒーリングMP+1');
INSERT INTO japanese_item (itemid, name, description) VALUES (5148, 'スキッドスシ', '炊いて握り固めたライスの上に、\nスキッドの生の切り身を乗せた東方伝来の料理。\nHP+30 DEX+6 AGI+5 MND-1 命中+15% (最大72)\n飛命+15% (最大72) レジストスリープ+1 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5149, 'ソールスシ', '炊いて握り固めたライスの上に、\nソールの生の切り身を乗せた東方伝来の料理。\nHP+20 STR+5 DEX+6 命中+15% (最大72)\n飛命+15% (最大72) レジストスリープ+1 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5150, 'トゥーナスシ', '炊いて握り固めたライスの上に、\nトゥーナの生の切り身を乗せた東方伝来の料理。\nHP+20 DEX+3 CHR+5 命中+15% (最大72)\n飛命+15% (最大72) レジストスリープ+1 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5151, 'アーチングンカン', '炊いて握り固めたライスを、海苔で囲んで船とし、\n中にアーチンの生殖巣を乗せた東方伝来の料理。\nHP+40 STR+1 VIT+5 命中+15% (最大72)\n飛命+15% (最大72) ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5152, '野牛の肉', '臭味がなく、とても美味なバッファローの肉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5153, 'トロスシ', '炊いて握り固めたライスの上に、\n脂肪に富むトゥーナの腹の切り身を乗せた料理。\nHP+20 DEX+3 CHR+5 命中+16% (最大76)\n飛命+16% (最大76) レジストスリープ+2 ');
