INSERT INTO japanese_item (itemid, name, description) VALUES (5156, 'ポーキュパインパイ', '美味しく焼けたヘッジホッグパイ。\nHP+55 STR+6 VIT+2 INT-3 MND+3 命中+5\n攻+18% (最大95) 飛攻+18% (最大95)');
INSERT INTO japanese_item (itemid, name, description) VALUES (5157, 'マーブルステーキ', '美味しく焼けた野牛の厚切り肉。\nジューシーで、食すると肉汁が溢れ出す。\nSTR+6 AGI+1 INT-3 攻+18% (最大95)\n飛攻+18% (最大95) リザードキラー+5');
INSERT INTO japanese_item (itemid, name, description) VALUES (5158, 'バーミリオンゼリー', '美味しく固めたクリムゾンゼリー。\n口中でクロットが動き、舌全体で旨味を味わえる。\nMP+12% (最大90) INT+6 ヒーリングMP+2 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5159, 'フライデラミザレオ', '美味しくあげたフィッシュ＆チップス。\nかつては、美味で知られたミザレオ海岸の魚を\n使ったもののみが、そう呼ばれていた。\nDEX+3 VIT+3 MND-3 飛命+7% (最大15) 防+5');
INSERT INTO japanese_item (itemid, name, description) VALUES (5160, 'アーチングンカン+1', '美味しく握れたアーチングンカン。\nHP+40 STR+1 VIT+5 命中+16% (最大76)\n飛命+16% (最大76) ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5161, 'リーダ風野菜炒め', '美味しく炒めたゴブリン風野菜炒め。\n呼称は、考案者のゴブリンに敬意を表したもの。\nVIT+2 AGI+5');
INSERT INTO japanese_item (itemid, name, description) VALUES (5162, 'スキッドスシ+1', '美味しく握れたスキッドスシ。\nHP+30 DEX+6 AGI+5 命中+16% (最大76)\n飛命+16% (最大76) レジストスリープ+2 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5163, 'ソールスシ+1', '美味しく握れたソールスシ。\nHP+20 STR+5 DEX+6 命中+16% (最大76)\n飛命+16% (最大76) レジストスリープ+2 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5164, 'ねりわさび', 'つんと鼻腔を刺激される東方伝来のスパイス。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5165, 'ムバルポロス水', 'ムバルポロスの天然水で有名な炭酸水。\nガス成分の影響か、飲むと声がちょっと高くなる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5166, 'クァールサンド', 'クァールのソテーを挟んだ白パン。\nMP+10 STR+5 AGI+1 INT-2\n攻+20% (最大75) 飛攻+20% (最大75)\nレジストスリープ+1 レジストスタン+4\nヒーリングHP+1');
INSERT INTO japanese_item (itemid, name, description) VALUES (5167, 'クァールサンド+1', '美味しくできたクァールサンド。\nMP+15 STR+5 AGI+1 INT-2\n攻+22% (最大80) 飛攻+22% (最大80)\nレジストスリープ+1 レジストスタン+4\nヒーリングHP+1 ');
