INSERT INTO japanese_item (itemid, name, description) VALUES (5217, 'サーモンの腹子', '淡水魚「シュヴァルサーモン」の卵巣。\n珍味で知られる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5218, 'サーモンロウ', 'サーモンの卵の塩漬け。\n「赤い貴石」と呼ばれている。\nHP+8 MP+8 DEX+2 MND-1');
INSERT INTO japanese_item (itemid, name, description) VALUES (5219, 'イクラグンカン', '炊いて握り固めたライスを、海苔で囲んで船とし、\n中にサーモンの卵を乗せた東方伝来の料理。\nHP+30 MP+10 DEX+3 MND-2\n命中+18% (最大28) 飛命+18% (最大28) ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5220, 'イクラグンカン+1', '美味しく握れたイクラグンカン。\nHP+30 MP+12 DEX+3 MND-1\n命中+18% (最大30) 飛命+18% (最大30) ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5221, '自家製ハーブティー', 'フェローが淹れてくれたハーブティー。\nほのかな香りが心を癒してくれる。\n命中+12% (最大80) 攻+10% (最大40)\n飛命+12% (最大80) 飛攻+10% (最大40)\nヒーリングHP+1 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5222, '自家製シチュー', 'フェローが煮込んでくれたシチュー。\n苦労の跡がうかがえる。\nVIT+1 命中+12% (最大80)\n攻+10% (最大40) 飛命+12% (最大80)\n飛攻+10% (最大40) ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5223, '自家製ジェラート', 'フェローが作ってくれたジェラート。\nとても冷えている。\nINT+1 命中+12% (最大80) 攻+10% (最大40)\n飛命+12% (最大80) 飛攻+10% (最大40) ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5224, '自家製おにぎり', 'フェローが握ってくれたおにぎり。\n力いっぱいぎゅっと握られている。\nDEX+1 命中+12% (最大80)\n攻+10% (最大40) 飛命+12% (最大80)\n飛攻+10% (最大40) ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5225, '自家製チーズ', 'フェローが作ってくれたチーズ。\n金属のように硬く、歯ごたえがある。\nHP+10 命中+12% (最大80)\n攻+10% (最大40) 飛命+12% (最大80)\n飛攻+10% (最大40) ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5226, '自家製ステーキ', 'フェローが焼いてくれたステーキ。\n熱々で肉汁がほとばしっている。\nSTR+1 命中+12% (最大80)\n攻+10% (最大40) 飛命+12% (最大80)\n飛攻+10% (最大40) ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5227, '自家製サラダ', 'フェローが和えてくれたサラダ。\n材料ひとつひとつが丁寧に切られている。\nMP+10 命中+12% (最大80)\n攻+10% (最大40) 飛命+12% (最大80)\n飛攻+10% (最大40) ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5228, '自家製パン', 'フェローが焼いてくれたパン。\n几帳面に形が整えられている。\n命中+12% (最大80) 攻+10% (最大40)\n飛命+12% (最大80) 飛攻+10% (最大40)\nヒーリングMP+1 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5229, '自家製リゾット', 'フェローが作ってくれたリゾット。\n高級食材がおしみなく用いられている。\nMND+1 命中+12% (最大80)\n攻+10% (最大40) 飛命+12% (最大80)\n飛攻+10% (最大40) ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5230, 'ラブチョコ', 'リボンと羊皮紙でラッピングされたハートチョコ。\nヒーリングMP+4');
