INSERT INTO japanese_item (itemid, name, description) VALUES (5414, '灯されたランプ', '豪華な装飾の施された青銅のランプ。\n口に灯された黒炎がちろちろと燃えている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5415, 'バルラーンの深省録', '勇者バルラーンの自叙伝。\n波瀾万丈の生涯を反映した記述は\n剣の極意から統治の技まで多岐にわたる。\nLv60～ All Jobs');
