INSERT INTO japanese_item (itemid, name, description) VALUES (5612, '鮟鱇鍋目付', '美味しくつつけるように\n食材の投入や手順が厳しく監視された鮟鱇鍋。\nHP+10% (最大200) MP+15 DEX+2 AGI+1\nMND+1 命中+15% (最大30)\n飛命+15% (最大30) ヒーリングHP+7\nヒーリングMP+2');
INSERT INTO japanese_item (itemid, name, description) VALUES (5613, '鮟鱇鍋奉行', 'みなが美味しくつつけるように\n見事に食材の投入や手順が采配された鮟鱇鍋。\nHP+10% (最大200) MP+20 DEX+4 AGI+2\nMND+2 命中+15% (最大45)\n飛命+15% (最大45) ヒーリングHP+9\nヒーリングMP+3');
INSERT INTO japanese_item (itemid, name, description) VALUES (5614, 'ケーニヒスクーヘン', 'タブナジア様式の星芒祭用ケーキ。\n輝く王冠が乗せられている。\nHP+8 MP+3% (最大13) INT+2\nヒーリングHP+1 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5615, '巌窟王', 'パティシエの技が光る「ケーニヒスクーヘン」。\nとてもとても美味しい。\nHP+10 MP+3% (最大15) INT+3\nヒーリングHP+2 ヒーリングMP+1 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5616, 'レープクーヘン', 'セルビナ様式の星芒祭用ケーキ。\n家の形状をしている。\nHP+8 MP+10% (最大45) INT+3\nヒーリングHP+2 ヒーリングMP+1 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5617, '人形の家', 'パティシエの技が光る「レープクーヘン」。\nとてもとても美味しい。\nHP+10 MP+10% (最大55) INT+4\nヒーリングHP+3 ヒーリングMP+2 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5618, '雑煮', '東方伝来の祝賀用スープ。\nHP+10 MP+10 STR+1 DEX+1 VIT+1\nAGI+1 命中+1 飛命+1 攻+1 飛攻+1 回避+1\nヒーリングHP+1 ヒーリングMP+1 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5619, '雑煮改', '美味しくできた雑煮。\nHP+12 MP+12 STR+2 DEX+2 VIT+2\nAGI+2 命中+2 飛命+2 攻+2 飛攻+2 回避+2\nヒーリングHP+1 ヒーリングMP+1 ');
