INSERT INTO japanese_item (itemid, name, description) VALUES (5691, 'シュリンプスシ', '炊いて握り固めたライスの上にバストア\nスイーパーの生の切り身を乗せた東方伝来の料理。\nVIT+1 命中+14% (最大68)\n飛命+14% (最大68) 防+5\nレジストスリープ+1 ');
