INSERT INTO japanese_item (itemid, name, description) VALUES (5707, '自家製オムレツ', 'フェローが作ってくれたオムレツ。\nふんわりと口中でとろける柔らかさ。\n命中+12% (最大80) 攻+10% (最大40)\n飛命+12% (最大80) 飛攻+10% (最大40) 防+5 ');
