INSERT INTO japanese_item (itemid, name, description) VALUES (5896, '消臭苔', '消臭効果があるという珍しい苔。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5897, '香木の根', '良い香りがする樹木の根。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5898, '影龍の頭骨', '悪夢をよびおこすドラゴンの頭骨。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5899, '影龍の骨', '悪夢をよびおこすドラゴンの大腿骨。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5900, '影龍の爪', '悪夢をよびおこすドラゴンの爪。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5901, '影龍の心臓', '悪夢をよびおこすドラゴンの心の臓。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5902, '牢獣の血', '魂の囚われた獣人の血液。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5903, '海坊主の毒墨', '毒性の強い頭足類の墨。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5904, '穿孔翼', '穴のあいた黒い翼。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5905, '不滅の破片', '不滅の象徴とされたゴーレムの破片。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5906, 'アブダルス魔道大全', 'コンフリクト推進派として有名な、\n魔道士アブダルス著の戦術魔道書の一部。\n紋章官必読の書。\nLv75～ All Jobs');
INSERT INTO japanese_item (itemid, name, description) VALUES (5907, 'ブロッコリー', '花蕾と花茎を食す多年草。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5908, 'アボカド', '非常に栄養価の高い果実。\nただし、食べ頃には注意が必要。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5909, 'ララブのしっぽ漬け', 'ララブのしっぽ亭名物の漬け物。\nその味付けは門外不出。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5910, 'メタルポーチ', '『ヘヴィメタル』を収納したハンドバッグ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5911, 'しっぽ亭の特製漬物', 'ララブのしっぽ亭で代々漬け込まれてきた古漬。\n深い風味とコクがある。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5912, '箙【ガーゴイル】', '『ガーゴイルアロー』を収納する武具。\n多数の矢を携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5913, '矢筒【アダマン】', '『アダマンボルト』を収納する武具。\n多数のボルトを携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5914, '胴乱【オリハル】', '『オリハルブレット』を収納する武具。\n多数のブレットを携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5915, '胴乱【アダマン】', '『アダマンブレット』を収納する武具。\n多数のブレットを携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5916, '王国風チョコ', '「神殿騎士団団長」クリルラから届いた\nプレゼント。\n菓子言葉『あなたを守ります』');
INSERT INTO japanese_item (itemid, name, description) VALUES (5917, 'シェルチョコ', '「ルジヌ魔法用品店」ルジヌから届いた\nプレゼント。\n※食べても魔法は覚えられません');
INSERT INTO japanese_item (itemid, name, description) VALUES (5918, 'ガトーサムライ', '「ミスリル銃士隊」アヤメから届いたプレゼント。\n侍憧れの一振りを模ったチョコレート。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5919, 'チョコサブリ', '「未来のファッションリーダー」ブリジッドから\n届いたプレゼント。\nサブリストに人気のサブリガ占い付き。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5920, 'ベリーボンボン', '「天の塔書記官」クピピから届いたプレゼント。\n食べやがれ！……なのなのです。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5921, 'しっぽチョコ', '「ララブのしっぽ亭」チャママから届いた\nプレゼント。\nピチチ垂涎のおやつ。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5922, 'クルミクッキー', '胡桃の入ったクッキー。\nバードキラー+10 レジストパライズ+10\nヒーリングHP+3 ヒーリングMP+6 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5923, 'ジャグランクッキー', '美味しく焼けたクルミクッキー。\nバードキラー+12 レジストパライズ+12\nヒーリングHP+5 ヒーリングMP+8 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5924, 'ヘルズバーグ', 'ケルベロスの挽き肉を焼いた料理。\nHP+30 STR+7 INT-5 攻+20% (最大160)\n飛攻+20% (最大160) ドラゴンキラー+5 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5925, 'ヘルズバーグ+1', '美味しく焼けたヘルズバーグ。\nHP+32 STR+8 INT-6 攻+22% (最大165)\n飛攻+22% (最大165) ドラゴンキラー+5 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5926, 'デーツティー', 'ほんのりとデーツの甘みと香りがする紅茶。\nHP+20 MP+30 VIT-1 INT+3 CHR+5 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5927, 'キャラバンティー', '美味しく淹れたデーツティー。\nHP+22 MP+32 INT+4 CHR+6 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5928, '姫様おにぎり', '姫様の愛情いっぱいのおにぎり。\nHP+25 DEX+4 VIT+4 CHR+4\n真の味:攻+60 防+40 トリプルアタック+1%');
INSERT INTO japanese_item (itemid, name, description) VALUES (5929, '皇女おにぎり', '魂をこめて握られた姫様おにぎり。\nHP+50 DEX+5 VIT+5 CHR+5\n真の味:攻+60 防+40 トリプルアタック+2%');
INSERT INTO japanese_item (itemid, name, description) VALUES (5930, 'ダンシングスープ', '踊り出すほど元気になると云うキノコのスープ。\nMP+30 MND+4 敵対心-4 ヒーリングMP+4 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5931, 'ツイストスープ', '美味しくできたダンシングスープ。\nMP+32 MND+5 敵対心-5 ヒーリングMP+5 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5932, 'キトロンジュース', 'キトロンの絞り汁。\nリフレシュ+3[180秒]');
INSERT INTO japanese_item (itemid, name, description) VALUES (5933, 'ドラゴン・オレ', 'ドラゴンフルーツ味のミルク。\nリジェネ+6[300秒]');
INSERT INTO japanese_item (itemid, name, description) VALUES (5934, 'チョコクッキー', 'チョコボの雛鳥の形に焼かれたクッキー。\nCHR+3 回避+2 アクアンキラー+10\nレジストサイレス+10 ヒーリングMP+3 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5935, 'モーグルト', 'モーグリが作ったヨーグルト。\n野牛の乳を使った、モーグリの自信作。\nHP+20% (最大20) VIT+3 ヒーリングHP+3 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5936, 'モグシューター', 'クパリカ王国伝来とされる祝祭用の打上花火。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5937, 'バブルブリーズ', '物悲しい美しさの水泡花火。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5938, '道すがらの呼び子', 'プログラムの途中で脱出する際、ミーブル族を呼ぶための笛。\n使用したメンバーだけが脱出することができる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5939, '終着の呼び子', 'プログラム達成後に脱出する際、ミーブル族を呼ぶための笛。\nパーティメンバー全員が脱出することができる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5940, 'ジャングルクッキー', '乾燥した果実の入ったクッキー。\nアドゥリン土産人気No.1。\nアクアンキラー+12 レジストスリープ+10\nヒーリングMP+5 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5941, 'フロンティアチョコ', '甘すぎないと評判の板状のチョコレート。\nアドゥリン土産人気No.3。\nMND+1 ヒーリングMP+2 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5942, 'カスケードドロップ', 'はじける泡が心地よいキャンディ。\nアドゥリン土産人気No.2。\nMND+4 CHR+4 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5943, 'アジェの干物', 'アジェを天日乾燥させた保存食。\nVIT-3 AGI+4 回避+5 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5944, 'クリアソーダ', 'アドゥリンで採れる天然の炭酸水。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5945, 'プライズパウダー', '塗布した者の姿を変える不思議な粉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5946, '古い袋【トリック】', '『トリックダイス』の入った袋。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5947, '古い袋【レジデ】', '『リミナルレジデ』の入った袋。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5948, 'ブラックプローン', 'センロー海周辺の海底に生息する甲殻類。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5949, 'ムセル', 'ウルブカ諸島の岩礁に附着する\n二枚貝の一種。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5950, 'アジェ', 'センロー海周辺に生息する海水魚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5951, 'レッドスポット', 'エヌティエル水林近海に生息する\n猛毒を持つ巨大海水魚。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5952, 'レッドシーマ', 'エヌティエル水林に生息する\n猛毒を持つ淡水魚。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5953, 'ヤマメ', '清流に生息する淡水魚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5954, 'バーナクル', 'センロー海周辺の岩礁に附着するバーナクル。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5955, 'クラリアス', 'ウルブカ大陸の地下深くに生息する珍しい\n巨大淡水魚。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5956, '.', 'itm_test');
INSERT INTO japanese_item (itemid, name, description) VALUES (5957, 'ビリビリ', '電気を発する珍しい淡水魚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5958, '.', 'itm_test');
INSERT INTO japanese_item (itemid, name, description) VALUES (5959, '龍魚', '汽水域にも生息する鱗の美しい淡水魚。\nアドゥリンでは観賞用として珍重される。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5960, 'ウルブカザリガニ', 'ウルブカ大陸に生息する甲殻類。\n毒に強い。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5961, 'コモンオクトパス', 'センロー海に生息している小型の頭足類。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5962, 'オクトパスの足', 'ちぎれた頭足類の足。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5963, 'センローサーディン', 'センロー海沿岸に生息する海水魚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5964, 'フィクリカ', 'ウルブカ大陸で人気の果実。\n寿命が延びると云われる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5965, 'チョイ', 'ウルブカ大陸に原産の葉を食す野菜。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5966, 'ウルブカパームの実', 'ウルブカ大陸で採れる固い殻に覆われている実。\n中はとてもジューシー。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5967, 'シャベリタケ', '食べると話が止まらなくなるキノコ。\n食用には適さない。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5968, 'シーフードパエリア', '様々な海の幸を贅沢に使ったパエリア。\nHP+40 DEX+5 MND-1 命中+15% (最大80)\nアンデッドキラー+5 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5969, '漁師風パエリア', 'センロー海が口の中に広がるパエリア。\nHP+45 DEX+6 命中+16% (最大85)\nアンデッドキラー+6 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5970, 'キノコパエリア', '様々なキノコを贅沢に使ったパエリア。\nHP+40 STR-1 MND+5 魔命+5\nアンデッドキラー+5 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5971, 'キノコパエリア+1', '大地の恵みを全身で感じられるパエリア。\nHP+45 MND+6 魔命+6 アンデッドキラー+6 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5972, '牛肉のパエリア', '牛肉を贅沢に使ったパエリア。\nHP+40 STR+5 INT-1 攻+18% (最大90)\nアンデッドキラー+5 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5973, '牛肉のパエリア+1', '牛肉とシーフードの旨みが溢れ出すパエリア。\nHP+45 STR+6 攻+19% (最大95)\nアンデッドキラー+6 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5974, 'バーナクルパエリア', 'バーナクルを贅沢に使ったパエリア。\nHP+40 VIT+5 MND-1 CHR-1\n防+25% (最大150) アンデッドキラー+5 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5975, 'フラパノパエリア', 'フラパノ直伝のバーナクルパエリア。\nあまりの美味しさに食材が足りなくなるのも\n頷ける。\nHP+45 VIT+6 防+26% (最大155)\nアンデッドキラー+6 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5976, 'パームジュース', 'パームの実をそのままに豪快に飲むジュース。\nアドゥリンの定番ジュース。\nVIT-2 CHR+3 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5977, 'パームジュース+1', '綺麗に切れただけなのにいつもより\n美味しく感じるパームジュース。\nVIT-1 CHR+4 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5978, 'フィクリカゼリー', 'フィクリカのゼリーにフィクリカのコンポートを\n乗せたデザート。\nMP+5% (最大100) INT+7 ヒーリングMP+3 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5979, '魅惑の歌声', 'パティシエの技が光る「フィクリカゼリー」。\nとてもとても美味しい。\nMP+6% (最大105) INT+8 ヒーリングMP+4 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5980, 'ボイルバーナクル', 'ボイルしたバーナクル。\nCHR-3 防+25% (最大130) ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5981, 'ボイルバーナクル+1', '美味しくできたボイルバーナクル。\nCHR-2 防+26% (最大135) ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5982, 'センロー風海の串焼', 'センロー海で採れる食材を刺したアドゥリン伝統の串焼。\nDEX+2 VIT+3 MND-1 防+25% (最大150) ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5983, '漁師風海の串焼', '美味しく焼けたセンロー風海の串焼。\n思わず泳ぎたくなる美味しさ。\nDEX+3 VIT+4 防+26% (最大155) ');
INSERT INTO japanese_item (itemid, name, description) VALUES (5984, 'ナットベイン', '食べると死に至るという毒草。\nナット族でさえも近寄らない。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5985, 'ヘムロック', '食べると「麻痺」状態になってしまう毒草。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5986, 'ワークスポーション', '開拓を進めるためにピースキーパー・ワークスが\n開発したポーション。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5987, 'ワークスエーテル', '開拓を進めるためにピースキーパー・ワークスが\n開発したエーテル。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5988, '呪符プロテス', '白魔法『プロテス』を封じた羊皮紙。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5989, '呪符シェル', '白魔法『シェル』を封じた羊皮紙。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5990, '呪符ストンスキン', '白魔法『ストンスキン』を封じた羊皮紙。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5991, 'スカーム帰巣蝶', '帰巣性の強い黒い蝶。\n放つと、迷うことなく元いた所に向け飛んでいく。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5992, '髑髏の鍵', '「スカーム」の宝箱を開くカギ。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5993, 'センローフロッグ', 'センロー海沿岸の岩礁に生息する両生類。');
INSERT INTO japanese_item (itemid, name, description) VALUES (5994, '.', 'itm_test');
INSERT INTO japanese_item (itemid, name, description) VALUES (5995, 'マリシアスパーチ', '食欲旺盛な猛毒を持つ巨大淡水魚。\n汽水域にも生息している。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5996, '.', 'itm_test');
INSERT INTO japanese_item (itemid, name, description) VALUES (5997, 'シン', '伝説の巨大二枚貝。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (5998, 'アドゥリンスープ', 'アドゥリンで一般的な海藻のスープ。\nHP+3% (最大40) VIT+3 防+15% (最大70)\nヒーリングHP+6');
INSERT INTO japanese_item (itemid, name, description) VALUES (5999, 'アドゥリンスープ+1', '美味しくできたアドゥリンスープ。\n懐かしさのあまり家に帰りたくなる味。\nHP+4% (最大45) VIT+4 防+16% (最大75)\nヒーリングHP+7');
INSERT INTO japanese_item (itemid, name, description) VALUES (6000, '.', 'itm_test');
INSERT INTO japanese_item (itemid, name, description) VALUES (6001, 'バファイクロット', '環境に適応して熱に強くなった\nスライム族の亜種「クロット」の小型の分身。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6002, 'ワークスつるはし', 'パイオニア・ワークスが改良した\n東ウルブカ専用のつるはし。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6003, 'ワークスつるはし+1', 'パイオニア・ワークスが改良した\n東ウルブカ専用のつるはし。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6004, 'ワークスまさかり', 'パイオニア・ワークスが改良した\n東ウルブカ専用のまさかり。');
