INSERT INTO japanese_item (itemid, name, description) VALUES (6100, 'インデパライズ', '使用制限:風Lv68\n風水魔法『インデパライズ』が記された風水盤。\n効果:自身の周囲の敵を「麻痺」状態にする。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6101, 'インデグラビデ', '使用制限:風Lv88\n風水魔法『インデグラビデ』が記された風水盤。\n効果:自身の周囲の敵を「ヘヴィ」状態にする。');
