INSERT INTO japanese_item (itemid, name, description) VALUES (6138, '箙【マンティス】', '『マンティッドアロー』を収納する武具。\n多数の矢を携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6139, '矢筒【ミドリウム】', '『ミドリウムボルト』を収納する武具。\n多数のボルトを携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6140, '矢筒【ダマスク】', '『ダマスクボルト』を収納する武具。\n多数のボルトを携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6141, '矢筒【オキシド】', '『オキシドボルト』を収納する武具。\n多数のボルトを携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6142, '胴乱【ミドリウム】', '『ミドリウムブレット』を収納する武具。\n多数のブレットを携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6143, '胴乱【ダマスク】', '『ダマスクブレット』を収納する武具。\n多数のブレットを携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6144, 'グラシアフィッシュ', 'ウルブカ大陸の氷河湖に生息する淡水魚。 \n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6145, 'ドワーフレモラ', '古代魚の幼魚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6146, 'レモラ', '伝説の巨大な古代魚。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6147, 'ミケの格闘術メモ', 'ミケ・アリョーチャが書いたメモ。\n「とにかく殴るにぁりん」と書かれている。\n格闘スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6148, '短剣指南書', '著者不明の短剣の教本。\n様々な状況で相手を一撃で暗殺する術が\n書かれている。\n短剣スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6149, '初めての片手剣', '後世の為にウラがキリッチに書かせた\n片手剣の教本。片手剣の握り方から\n足の出し方まで丁寧に書かれている。\n片手剣スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6150, 'ミュゼルワール日誌', 'ミュゼルワール・B・アンシェルの戦闘日誌。\nボスディン氷河での巨人との戦いが記されている。\n両手剣スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6151, 'グジャカ日誌', 'グジャカの第二次コンシュタット会戦日誌。\n共和国軍が狼王ルジーグ率いる\nサンドリア王国軍に勝利した戦いが記されている。\n片手斧スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6152, '破壊のススメ', '著者不明の両手斧の教本。\n物の壊し方が長々と記されている。\n両手斧スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6153, 'ルートヴィヒ報告書', 'ルートヴィヒ・アイヒベルクが書いた\nグロウベルグ会戦の報告書。\n戦線の推移や撤退時の戦いなどが記されている。\n両手鎌スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6154, 'サンドリア大衆記事', 'サンドリアで流行した大衆紙の記事。\n演習でのイルヴォレール・Ｓ・クスローと\nアルフォニミル・Ｍ・オルシャーの一騎打ちのことが\n書かれている。\n両手槍スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6155, 'カゲトラ日録', 'カゲトラの日誌。\nヨミとの対戦成績が書いてある。98勝99敗。\n片手刀スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6156, 'ノユリの東方見聞録', 'ノユリのひんがし見聞録。\n免許皆伝の為に巨大な怪物を討伐した時のことが\n記されている。\n両手刀スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6157, 'フェリアス北方手記', 'フェリアスコフィンの日記。\n北の国で数々のオークを戦槌の錆にしたことが\n書かれている。\n片手棍スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6158, 'カイルパイル回想録', 'カイルパイルが書き記した日誌。\n大魔元帥ロベルアクベルからクラウストルムを\n授かった日のことが詳細に書かれている。\n両手棍スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6159, 'ペリィ式弓術教本', 'ペリィ・ヴァシャイが新兵の為に書いた弓術の\n手引き。弓の構えや射程の見極め方など\n丁寧に書かれている。\n弓術スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6160, '銃解体書', 'エリヴィラ・ゴーゴリが書き記した教本。\n銃の構造や組み立て方など詳細に書かれている。\n射撃スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6161, '投てき指南書', '著者不明の投てきの教本。\n遠くから相手に気がつかれずに暗殺する術が\n書かれている。\n投てきスキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6162, 'ミケのガードメモ', 'ミケ・アリョーチャが書いたメモ。\n「とにかく守るにぁりん」と書かれている。\nガードスキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6163, 'ソニアのノート', 'アニカ・ブリリオートに憧れた\nソニア・アルフォンソのクリークタンツの練習帳。\n回避スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6164, 'とある盾の継承', 'セラーヌ・Ｉ・ヴィルゴの日誌。\nペルセウスから盾を預かった夜のことが\n記されている。\n盾スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6165, 'カゲトラの訓練日誌', 'カゲトラの日誌。\nヨミと切磋琢磨した日々が書かれている。\n受け流しスキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6166, 'アルタナの聖歌', 'フェブルナルド・Ｃ・ブリュノーの愛読書。\n女神アルタナの聖歌が書かれている。\n神聖魔法スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6167, 'コヴェフ墳墓群記文', 'フェリアスコフィンの日記。\nコヴェフ墳墓群に立ち寄った時のことが\n記されている。\n回復魔法スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6168, '魔法剣の真髄', 'ライニマードが書いた強化魔法の教本。\n魔法剣の扱い方が丁寧に記されている。\n強化魔法スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6169, '手配書一覧', 'ライニマードが書いた探偵業の日誌。\n相手の癖や思考が細かに書かれている。\n弱体魔法スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6170, '賞金首目録', 'アズィマが記した賞金首の一覧。\n全ての名前に×印が書かれている。\n精霊魔法スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6171, 'アズィマの暗黒魔法', 'アズィマが書いた暗黒魔法の教本。\nあまりに難解すぎて一部の人間にしか\n理解されなかった。\nこの本の少ない売り上げが錬金術の書籍購入資金に\nなっている。\n暗黒魔法スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6172, '光風の詩', 'ルーウェンハートが書き残した歌唱の歌詞。\n光風のエチュード。\n歌唱スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6173, '岩窟のスコア', 'ルーウェンハートが書き残した弦楽器の楽譜。\n岩窟のエチュード。\n弦楽器スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6174, '木漏れ日のスコア', 'ルーウェンハートが書き残した管楽器の楽譜。\n木漏れ日のエチュード。\n管楽器スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6175, 'ヨミの忍具図解', 'ヨミがカゲトラの為に書いた忍具の作り方。\n図解で丁寧に書かれている。\n忍術スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6176, '神獣空想本', '著者不明のとても古い幻想書籍。\n神獣が住む世界のことが書かれている。\n召喚魔法スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6177, '生体研究書', '著者不明の生物の生体研究書。\n多種多様な生物の研究が記されている。\n青魔法スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6178, 'ホロージュ実記', 'ホロージュ・ワグレッサが書き残した記録。\n龍脈の暴走を鎮めた日のことが記されている。\n風水魔法スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6179, '風水鈴伝説', 'ホロージュ・ワグレッサが書き残した日録。\nシィ・レナイェの風水鈴と大地の声の\n伝承について記されている。\n風水鈴スキルが上昇する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6180, '小箱【深成岩】', '小さな木製の箱。\n「深成岩」がしょうしょう入っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6181, '小包【餅鉄】', '小さな小包。\n「餅鉄」がしょうしょう入っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6182, '小箱【ボウルダー】', '小さな青銅の箱。\n「リフトボウルダー」がしょうしょう入っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6183, '大箱【深成岩】', '大きな木製の箱。\n「深成岩」がざくざく入っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6184, '大箱【餅鉄】', '大きな木製の箱。\n「餅鉄」がざくざく入っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6185, '大箱【ボウルダー】', '大きな青銅の箱。\n「リフトボウルダー」がざくざく入っている。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6186, 'スライムロケット', '異世界のモンスターを題材にした打上花火。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6187, 'スライムドロップ', '異世界のモンスターの姿を模したキャンデー。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6188, 'ベスドロップ', '異世界のモンスターの姿を模したキャンデー。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6189, 'メタスラドロップ', '異世界のモンスターの姿を模したキャンデー。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6190, 'スプリガンスパーク', '異世界のモンスターを題材にした吹出花火。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6191, 'スプリガンロリーＧ', '異世界のモンスターの姿を模したキャンデー。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6192, 'スプリガンロリーＲ', '異世界のモンスターの姿を模したキャンデー。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6193, 'スプリガンロリーＰ', '異世界のモンスターの姿を模したキャンデー。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6194, 'ソーマの雫【氷湖】', 'カミール山麓で抽出した\nエルゴンパワーを封じた魔瓶。\n一時的にモクシャが上昇する効果を得る。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6195, 'ソーマの雫【輝滴】', 'カミール山麓で抽出した\nエルゴンパワーを封じた魔瓶。\n一時的にコンサーブMPが上昇する効果を得る。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6196, 'ソーマの雫【飛泉】', 'ウォーの門で抽出した\nエルゴンパワーを封じた魔瓶。\n一時的にストアTPが上昇する効果を得る。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6197, 'ソーマの雫【凍石】', 'ウォーの門で抽出した\nエルゴンパワーを封じた魔瓶。\n一時的に魔法防御力が上昇する効果を得る。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6198, 'ソーマの雫【氷爪】', 'カミール山麓で抽出した\nエルゴンパワーを封じた魔瓶。\n一時的にスナップショットが上昇する効果を得る。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6199, '箙【アチヤル】', '『アチヤルアロー』を収納する武具。\n多数の矢を携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6200, '箙【アドリブン】', '『アドリブンアロー』を収納する武具。\n多数の矢を携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6201, '箙【トゥルフェア】', '『トゥルフェアアロー』を収納する武具。\n多数の矢を携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6202, '箙【ラズ】', '『ラズアロー』を収納する武具。\n多数の矢を携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6203, '矢筒【アチヤル】', '『アチヤルボルト』を収納する武具。\n多数のボルトを携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6204, '矢筒【アドリブン】', '『アドリブンボルト』を収納する武具。\n多数のボルトを携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6205, '矢筒【チタン】', '『チタンボルト』を収納する武具。\n多数のボルトを携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6206, '矢筒【ビスマス】', '『ビスマスボルト』を収納する武具。\n多数のボルトを携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6207, '胴乱【アチヤル】', '『アチヤルブレット』を収納する武具。\n多数のブレットを携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6208, '胴乱【アドリブン】', '『アドリブンブレット』を収納する武具。\n多数のブレットを携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6209, '胴乱【チタン】', '『チタンブレット』を収納する武具。\n多数のブレットを携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6210, '胴乱【ビスマス】', '『ビスマスブレット』を収納する武具。\n多数のブレットを携帯できる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6211, 'Ｓ．マリナーラピザ', 'ニンニクとトマトを乗せた船乗り風ピザの一切れ。\nHP+20 命中+10% (最大54)\n攻+20% (最大50) アンデッドキラー+5 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (6212, 'Ｓ．マリナーラ+1', '美味しく焼けたマリナーラピザの一切れ。\nHP+25 命中+11% (最大58)\n攻+21% (最大55) アンデッドキラー+5');
