INSERT INTO japanese_item (itemid, name, description) VALUES (6458, '醤油ラーメン', '醤油スープの中に麺を入れて様々な具材を乗せた\n東方で人気の料理。\nHP+50 STR+5 VIT+5 AGI+3\n攻+10% (最大170) 飛攻+10% (最大170)\nレジストスロウ+10');
