INSERT INTO japanese_item (itemid, name, description) VALUES (6460, '味噌ラーメン', '味噌スープの中に麺を入れて様々な具材を乗せた\n東方で人気の料理。\nHP+100 STR+5 VIT+5 防+10% (最大170)\n魔回避+10% (最大50) 魔防+5\nレジストスロウ+10');
INSERT INTO japanese_item (itemid, name, description) VALUES (6461, '味噌ラーメン+1', '職人の魂が籠った味噌ラーメン。\nHP+105 STR+6 VIT+6 防+11% (最大175)\n魔回避+11% (最大55) 魔防+6\nレジストスロウ+15');
INSERT INTO japanese_item (itemid, name, description) VALUES (6462, '塩ラーメン', '塩スープの中に麺を入れて様々な具材を乗せた\n東方で人気の料理。\nDEX+5 VIT+5 AGI+5 命中+5% (最大90)\n飛命+5% (最大90) 回避+5% (最大90)\nレジストスロウ+10');
INSERT INTO japanese_item (itemid, name, description) VALUES (6463, '塩ラーメン+1', '職人の魂が籠った塩ラーメン。\nDEX+6 VIT+6 AGI+6 命中+6% (最大95)\n飛命+6% (最大95) 回避+6% (最大95)\nレジストスロウ+15');
INSERT INTO japanese_item (itemid, name, description) VALUES (6464, 'ベヒーモステーキ', '厚切りで焼いたベヒーモスの肉。\nHP+40 STR+7 DEX+7 INT-3\n攻+23% (最大160) 飛攻+23% (最大160)\nトリプルアタック+1% リザードキラー+4\nヒーリングHP+4 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (6465, 'ベヒーモステーキ+1', '美味しく焼けたベヒーモスの厚切り肉。\nあまりの美味しさに叫びそうになってしまう。\nHP+45 STR+8 DEX+8 INT-4\n攻+24% (最大165) 飛攻+24% (最大165)\nトリプルアタック+2% リザードキラー+5\nヒーリングHP+5 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (6466, '味噌汁', '東方の家庭で一般的な味噌汁。\nHP+7% (最大50) DEX+4 AGI+4\n命中+10% (最大40) 攻+10% (最大40)\n飛命+10% (最大40) 飛攻+10% (最大40)');
INSERT INTO japanese_item (itemid, name, description) VALUES (6467, '味噌汁+1', '美味しくできた味噌汁。\n身体も心もぽかぽかになる。\nHP+8% (最大55) DEX+5 AGI+5\n命中+11% (最大45) 攻+11% (最大45)\n飛命+11% (最大45) 飛攻+11% (最大45)');
INSERT INTO japanese_item (itemid, name, description) VALUES (6468, '特上スシ', '様々な種類のネタで盛られた豪華なスシ。\nHP+40 MP+20 STR+6 DEX+7 MND-3\nCHR+6 命中+10% (最大100) 飛命+10% (最大100)\nレジストスリープ+1 ');
INSERT INTO japanese_item (itemid, name, description) VALUES (6469, '特上スシ+1', '美味しくできた特上スシ。\nHP+45 MP+25 STR+7 DEX+8 MND-4\nCHR+7 命中+11% (最大105) 飛命+11% (最大105)\nレジストスリープ+2 ');
