INSERT INTO japanese_item (itemid, name, description) VALUES (6575, 'チーズステーキ', '味付けされた野牛の肉と溶けたチーズをパンで\n挟んだ料理。\nSTR+5 DEX+3 VIT+5 AGI+3 INT-5 MND-5\n攻+25% (最大70) 防+25% (最大70) ');
INSERT INTO japanese_item (itemid, name, description) VALUES (6576, 'ロランベリーターキ', 'ローストした西方原産の食用鳥に\nたっぷりのロランベリーソースをかけた料理。\n祭典に振舞われる。\nSTR+10 攻+20% (最大120)\n飛攻+20% (最大120) カウンター+10\nレジストアムネジア+10 ');
