INSERT INTO japanese_item (itemid, name, description) VALUES (6580, 'ラステクフィッシュ', 'タブナジア地方で採れる食材を使った伝統料理。\n少し辛い。\n命中+10% (最大50) 魔命+10% (最大50)\n回避+10% (最大50) 魔回避+10% (最大50)\nリジェネ+2 ');
