INSERT INTO japanese_item (itemid, name, description) VALUES (6683, 'ポーセレンマイン', 'ジュノの技師が20周年を記念して開発した、式典用の花火。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6684, 'ポッパーII', '若手錬金術師が製造した、友への祝意を表した\n花火。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6685, 'カザナル帰巣蝶', '帰巣性の強い黒い蝶。\n放つと、迷うことなく元いた所に向け飛んでいく。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6686, '牛丼', '野牛の肉とワイルドオニオンなどの食材を\n煮込んでタルタルライスの上にのせた丼物。\n敵対心-5 ダブルアタック+5%\nウェポンスキルのダメージ+5%');
INSERT INTO japanese_item (itemid, name, description) VALUES (6687, '牛丼+1', '美味しくできた牛丼。\n敵対心-6 ダブルアタック+6%\nウェポンスキルのダメージ+6%');
INSERT INTO japanese_item (itemid, name, description) VALUES (6688, 'チャチャルンの夷袋', 'チャチャルンが精選した福袋。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6689, '大きな白い尻尾', '非常に大きな白い尻尾。\nもふもふしている。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6690, '譜面：星芒祭', 'オーケストリオンで聴くことができる楽曲の譜面。\n＜楽曲リスト＞ \n　Jeuno -Starlight Celebration-');
INSERT INTO japanese_item (itemid, name, description) VALUES (6691, '譜面：マウント', 'オーケストリオンで聴くことができる楽曲の譜面。\n＜楽曲リスト＞ \n　Full Speed Ahead!');
INSERT INTO japanese_item (itemid, name, description) VALUES (6692, '実験場の試験薬', 'シェルマペルが実験場から持ってきた試験薬。\n服用できるようだが……。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6693, 'インプの霧笛', 'インプが秘密裏に携帯している角笛。\n誰でも鳴らせるようだが……。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6694, 'チョコボチェアII', 'チョコボチェアIIを組み立てるキット。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6695, 'アデニウムベンチ', 'アデニウムベンチを組み立てるキット。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6696, '譜面：近東', 'オーケストリオンで聴くことができる楽曲の譜面。\n＜楽曲リスト＞ \n　Bustle of the Capital／Jeweled Boughs\n　Bandits'' Market／Illusions in the Mist');
INSERT INTO japanese_item (itemid, name, description) VALUES (6697, '呪符リレイズIII', '白魔法『リレイズIII』を封じた羊皮紙。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6698, '魔行符：白門', '高位の転送魔法が封じられた呪符。\n転送先：アトルガン白門。');
INSERT INTO japanese_item (itemid, name, description) VALUES (6699, '透明薬', '姿、音、臭いを消す薬。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6700, 'モーグリの覚書', 'ピルグリムモーグリ流のオデシーの歩き方が\n記されている。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6701, 'ラミアパウダー', '塗布した者の姿をラミアに変える不思議な粉。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (6702, 'ペイスト薬', 'ペイストの姿に変身できる霊薬。\n');
