INSERT INTO japanese_item (itemid, name, description) VALUES (8449, 'ストロボ', '敵対心アップの効果。\n「挑発」を使用する場合がある。');
INSERT INTO japanese_item (itemid, name, description) VALUES (8450, 'Ｔ．スプリング', '攻撃力アップの効果。');
INSERT INTO japanese_item (itemid, name, description) VALUES (8451, 'インヒビター', 'ストアTPの効果。\nTPを効率よく使う。');
INSERT INTO japanese_item (itemid, name, description) VALUES (8452, 'Ｔ．スプリングII', '攻撃力アップの効果。');
INSERT INTO japanese_item (itemid, name, description) VALUES (8453, 'アチューナー', '強い敵に対して、攻撃力アップの効果。');
INSERT INTO japanese_item (itemid, name, description) VALUES (8454, 'Ｒ．シールド', '「ブレイズスパイク」を使用する。');
INSERT INTO japanese_item (itemid, name, description) VALUES (8455, 'フレイムホルダー', 'ウェポンスキル発動時、\nファイアマニューバの数に応じた\nダメージアップ。\nただし、ファイアマニューバの負荷がかかる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (8456, 'ヒートキャパシター', 'ファイアマニューバの数に応じた\nTPを得る。\nただし、ファイアマニューバの負荷がかかる。');
INSERT INTO japanese_item (itemid, name, description) VALUES (8457, 'ストロボII', '敵対心アップの効果。\n「挑発」を使用する場合がある。');
INSERT INTO japanese_item (itemid, name, description) VALUES (8458, 'Ｔ．スプリングIII', '攻撃力アップの効果。');
