INSERT INTO japanese_item (itemid, name, description) VALUES (9774, 'オークの供物', 'オーク族の供物。\nアルタナ全席に使われたサンドリアの伝統料理。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (9775, 'クゥダフの供物', 'クゥダフ族の供物。\nアルタナ全席に使われたバストゥークの伝統料理。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (9776, 'ヤグードの供物', 'ヤグード族の供物。\nアルタナ全席に使われたウィンダスの伝統料理。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (9777, 'ゴブリンの供物', 'ゴブリン族の供物。\nアルタナ全席に使われたジュノの伝統料理。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (9778, 'イロハからの手紙', '師匠へ\n稽古をつけていただきとうございます。\n醴泉神社にてお待ちしておりますゆえ、\nよろしく頼み申します。\nイロハ');
INSERT INTO japanese_item (itemid, name, description) VALUES (9779, '宮司からの招待状', '拝啓　冒険者殿\n此度の祭祀にご参列賜りたく候。\n醴泉神社にてお待ち申しております。\n敬具　醴泉神社　宮司');
INSERT INTO japanese_item (itemid, name, description) VALUES (9780, 'Ａ．チケット：武器', '冒険者互助会発行の引換券。\nアンバスケードの戦利品と交換できる。\n引換アイテム：アブダルス特製の武器とグリップ');
