INSERT INTO japanese_item (itemid, name, description) VALUES (16992, 'ブリ切り身', 'ブルーテールやウスクムルの切り身。\n釣り餌。大物に有効。');
INSERT INTO japanese_item (itemid, name, description) VALUES (16993, 'むきザリガニ', 'ザリガニのむき身。\n釣り餌。大物に有効。');
INSERT INTO japanese_item (itemid, name, description) VALUES (16994, 'フナ切り身', '堀ブナの切り身。\n釣り餌。');
INSERT INTO japanese_item (itemid, name, description) VALUES (16995, '腐肉', '腐敗した動物の肉。\n鼻をつく悪臭がする。');
INSERT INTO japanese_item (itemid, name, description) VALUES (16996, 'イワシダンゴ', 'サーディンのすり身と穀物を練り合わせたダンゴ。\n釣り餌。');
INSERT INTO japanese_item (itemid, name, description) VALUES (16997, 'エビダンゴ', 'ロブスターのすり身と穀物を練り合わせたダンゴ。\n釣り餌。');
INSERT INTO japanese_item (itemid, name, description) VALUES (16998, '虫ダンゴ', '潰した蟲と穀物を練り合わせたダンゴ。\n釣り餌。');
INSERT INTO japanese_item (itemid, name, description) VALUES (16999, 'マスダンゴ', 'ヒカリマスやアラバルウのすり身と\n穀物を練り合わせたダンゴ。釣り餌。');
INSERT INTO japanese_item (itemid, name, description) VALUES (17000, '肉ダンゴ', 'ひき肉と穀物を練り合わせたダンゴ。\n釣り餌。');
INSERT INTO japanese_item (itemid, name, description) VALUES (17001, '大ヨロイ蟲', '「ドレッドバグ」のひだに寄生する蟲。\n釣り餌。');
INSERT INTO japanese_item (itemid, name, description) VALUES (17002, 'ロバー針', '発光する鉤を無数に組み合わせた釣りの仕掛け。\n魚に引っ掛けて釣る。');
INSERT INTO japanese_item (itemid, name, description) VALUES (17003, 'ポイ', '「金魚すくい」で水中の金魚を捕獲する道具。\n主要部はごく薄い靭皮紙でできており、\n破損し易い。');
INSERT INTO japanese_item (itemid, name, description) VALUES (17004, 'ジャッジミノー', '小魚が尾をふって泳ぐ絡繰擬餌。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (17005, 'ルフェーゼ蝿', 'ルフェーゼ野で採れる、元気だが無鉄砲なハエ。\nよく目立ち、フロッグフィッシングの餌に最適。');
INSERT INTO japanese_item (itemid, name, description) VALUES (17006, 'ドリルカラマリ', '尖がった殻が特徴的な小型の頭足類。\n釣り餌。');
INSERT INTO japanese_item (itemid, name, description) VALUES (17007, 'ドワーフプギル', '非常に珍しい小型の陸魚類。\n釣り餌。');
INSERT INTO japanese_item (itemid, name, description) VALUES (17008, 'ＭＭＭダンゴＳ', '様々な具材が練りこまれたダンゴ。\nＭＭＭ社特製の釣り餌。');
INSERT INTO japanese_item (itemid, name, description) VALUES (17009, 'ＭＭＭダンゴＬ', '様々な具材が練りこまれたダンゴ。\nＭＭＭ社特製の釣り餌。大物に有効。');
INSERT INTO japanese_item (itemid, name, description) VALUES (17010, 'ゴライアスワーム', '地中に生息する大型の環虫。\n巨人族が好物の魚を釣るのに用いる。\n釣り餌。');
INSERT INTO japanese_item (itemid, name, description) VALUES (17011, '恵比寿釣竿', '東方の神話に登場する竿に似た伝説の釣り竿。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (17012, 'ジャッジロッド', '釣り竿。');
INSERT INTO japanese_item (itemid, name, description) VALUES (17013, 'お椀', '水を満たした容器。\n「金魚すくい」で捕獲した金魚を入れておく。');
INSERT INTO japanese_item (itemid, name, description) VALUES (17014, 'ヒューム式釣竿', 'ヒューム伝統の木製釣り竿。\n');
INSERT INTO japanese_item (itemid, name, description) VALUES (17015, 'ハルシオンロッド', '錬金術ギルドで開発された人工素材の釣り竿。\n');
