DROP TABLE IF EXISTS `custom_char_reword`;
CREATE TABLE IF NOT EXISTS `custom_char_reword` (
  `charid` int(10) unsigned NOT NULL,
  `category` varchar(128) NOT NULL,
  `item` varchar(128) NOT NULL,
  `status` int(8) NOT NULL DEFAULT 0,
  PRIMARY KEY (`charid`,`category`,`item`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `custom_char_area_enemy`;
CREATE TABLE IF NOT EXISTS `custom_char_area_enemy` (
  `charid` int(10) unsigned NOT NULL,
  `zoneid` tinyint(3) unsigned NOT NULL,
  `count` int(10) unsigned NOT NULL,
  PRIMARY KEY (`charid`,`zoneid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `custom_inventory`;
CREATE TABLE `custom_inventory` (
  `charid` int(10) unsigned NOT NULL,
  `location` tinyint(1) unsigned NOT NULL DEFAULT '0',
  `slot` tinyint(2) unsigned NOT NULL DEFAULT '0',
  `itemId` smallint(5) unsigned NOT NULL DEFAULT '65535',
  `quantity` int(10) unsigned NOT NULL DEFAULT '0',
  `bazaar` int(8) unsigned NOT NULL DEFAULT '0',
  `signature` varchar(20) NOT NULL DEFAULT '',
  `extra` blob(24) DEFAULT NULL,
  PRIMARY KEY (`charid`,`location`,`slot`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AVG_ROW_LENGTH=28;

DROP TABLE IF EXISTS `japanese_item`;
CREATE TABLE `japanese_item` (
  `itemid` smallint(5) unsigned NOT NULL,
  `name` tinytext NOT NULL,
  `description` text NOT NULL,
  PRIMARY KEY (`itemid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `custom_open_recipes`;
CREATE TABLE `custom_open_recipes` (
  `charid` int(10) unsigned NOT NULL,
  `ID` mediumint(5) unsigned NOT NULL,
  PRIMARY KEY (`charid`,`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;




